const state={myStore:null,backendStats:null,route:location.hash.slice(2)||'home',q:'',cat:'All',location:'Any location',user:null,favs:JSON.parse(localStorage.getItem('sut_favs')||'[]'),theme:localStorage.getItem('sut_theme')||'dark',lang:localStorage.getItem('sut_lang')||'en',menu:false,buyForMe:null,share:null,requests:[],products:[],stores:[],sutMessages:[],sutMessagesLoaded:false,sutMessagesLoading:false};
const T={en:{home:'Home',products:'Products',stores:'Stores',requests:'Public Request',about:'About',account:'Account',help:'Help Centre',wishlist:'Wishlist',settings:'Settings',seller:'Become a Seller',dashboard:'Store Dashboard',signIn:'Sign in',media:'Media',contact:'Contact'},sw:{home:'Mwanzo',products:'Bidhaa',stores:'Maduka',requests:'Ombi la Umma',about:'Kuhusu',account:'Akaunti',help:'Kituo cha Msaada',wishlist:'Vipendwa',settings:'Mipangilio',seller:'Kuwa Muuzaji',dashboard:'Store Dashboard',signIn:'Ingia',media:'Media',contact:'Mawasiliano'},fr:{home:'Accueil',products:'Produits',stores:'Boutiques',requests:'Demande publique',about:'À propos',account:'Compte',help:'Centre d’aide',wishlist:'Favoris',settings:'Paramètres',seller:'Devenir vendeur',dashboard:'Tableau vendeur',signIn:'Connexion',media:'Média',contact:'Contact'},ar:{home:'الرئيسية',products:'المنتجات',stores:'المتاجر',requests:'طلب عام',about:'حول',account:'الحساب',help:'مركز المساعدة',wishlist:'المفضلة',settings:'الإعدادات',seller:'كن بائعاً',dashboard:'لوحة المتجر',signIn:'تسجيل الدخول',media:'الوسائط',contact:'اتصل بنا'},zh:{home:'首页',products:'产品',stores:'商店',requests:'公开请求',about:'关于',account:'账户',help:'帮助中心',wishlist:'收藏',settings:'设置',seller:'成为卖家',dashboard:'店铺后台',signIn:'登录',media:'媒体',contact:'联系我们'}};
const tr=k=>T[state.lang]?.[k]||T.en[k]||k; const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])); const money=n=>new Intl.NumberFormat('en-TZ').format(n)+' TZS'; const prod=id=>{const x=state.products.find(v=>String(v[0])===String(id));if(!x)return null;return{id:x[0],title:x[1],cat:x[2],price:Number(x[3])||0,seller:x[4],loc:x[5],img:x[7]||'assets/sut-icon.png',storeId:x[8],currency:x[10]||'TZS',availability:x[11]||'available'}}; const fav=id=>state.favs.includes(id); const isSeller=()=>!!state.user&&(!!state.myStore||!!state.user?.roles?.some(r=>['seller','admin','superadmin'].includes(r))); const isAdmin=()=>!!state.user?.roles?.some(r=>['admin','superadmin'].includes(r));
function toast(m){const e=document.createElement('div');e.className='toast';e.textContent=m;document.body.append(e);setTimeout(()=>e.remove(),2400)}
function go(r){location.hash='#/'+r} function setCat(category){state.cat=String(category||'All');state.q='';state.location='Any location';go('products')} window.addEventListener('hashchange',()=>{const next=location.hash.slice(2)||'home';if(state.buyForMe && !next.startsWith('request'))state.buyForMe=null;state.route=next;state.menu=false;render();scrollTo(0,0)});
function toggleTheme(){state.theme=state.theme==='light'?'dark':'light';localStorage.setItem('sut_theme',state.theme);render()}
function setLang(v){state.lang=v;localStorage.setItem('sut_lang',v);render()}
function openMenu(){state.menu=true;render()} function closeMenu(){state.menu=false;render()}
let deferredInstallPrompt=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;document.querySelectorAll('[data-install-app]').forEach(x=>{x.style.display='inline-flex';x.textContent='Install App'})});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;document.querySelectorAll('[data-install-app]').forEach(x=>{x.style.display='none';x.textContent='SUT Installed';x.disabled=true});toast('SUT installed successfully')});
if(window.matchMedia('(display-mode: standalone)').matches){document.querySelectorAll('[data-install-app]').forEach(x=>{x.style.display='none';x.textContent='SUT Installed';x.disabled=true})}
async function installApp(){if(window.matchMedia('(display-mode: standalone)').matches){toast('SUT is already installed');return}if(deferredInstallPrompt){deferredInstallPrompt.prompt();const r=await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;if(r.outcome==='accepted')toast('Installing SUT…');return}toast('Use your browser menu and choose Add to Home screen / Install App')}

function head(){const r=state.route.split('/')[0];return `<header class="top"><a class="brand" href="#/home" aria-label="Star Universal Trade home"><img class="brand-icon" src="assets/sut-icon.png" alt="SUT"><span class="brand-name"><b><i>STAR</i> <em>UNIVERSAL</em> <i>TRADE</i></b><small>Rex International Technologies</small></span></a><nav class="nav">${[['home','home'],['products','products'],['stores','stores'],['requests','requests']].map(([id,k])=>`<button class="${r===id?'on':''}" onclick="go('${id}')">${tr(k)}</button>`).join('')}</nav><div class="actions"><button class="icon theme-toggle" title="Light / Dark mode" aria-label="Toggle dark mode" onclick="toggleTheme()">${state.theme==='light'?'☾':'☀'}</button><button class="btn primary install-button" data-install-app onclick="installApp()"><span aria-hidden="true">↓</span><span>Install App</span></button><button class="btn primary desktop" onclick="go(state.user?'account':'login')">${state.user?tr('account'):tr('signIn')}</button><button class="icon menu-toggle" aria-label="Open menu" title="Menu" onclick="openMenu()">☰</button></div></header>`}
function sideMenu(){let links=[['home','home'],['products','products'],['stores','stores'],['requests','requests'],['wishlist','wishlist'],['notifications','Notifications'],['account','account'],['help','help'],['settings','settings'],['about','about']];if(!state.user)links=links.filter(x=>!['settings'].includes(x[0]));if(isSeller())links.splice(links.findIndex(x=>x[0]==='account')+1,0,['seller-dashboard','dashboard']);if(!isSeller())links.splice(links.findIndex(x=>x[0]==='account')+1,0,['seller','seller']);if(isAdmin())links.push(['admin','Admin Console']);return `<div class="menu-overlay ${state.menu?'open':''}" onclick="closeMenu()"><aside class="side-menu" onclick="event.stopPropagation()"><button class="icon close" onclick="closeMenu()">×</button><div class="menu">${links.map(x=>`<button onclick="go('${x[0]}');closeMenu()">${x[0]==='admin'?'Admin Console':tr(x[1])}${x[0]==='notifications'&&((state.sutMessages||[]).filter(n=>!n.read_at&&!n.deleted_at).length)?` <span class="badge">${(state.sutMessages||[]).filter(n=>!n.read_at&&!n.deleted_at).length}</span>`:''}</button>`).join('')}<button onclick="go('privacy');closeMenu()">Privacy Policy</button><button onclick="go('terms');closeMenu()">Terms of Service</button><div style="border-top:1px solid var(--line);margin-top:12px;padding-top:12px"><select class="input" onchange="setLang(this.value)"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="sw" ${state.lang==='sw'?'selected':''}>Swahili</option><option value="fr" ${state.lang==='fr'?'selected':''}>Français</option><option value="ar" ${state.lang==='ar'?'selected':''}>العربية</option><option value="zh" ${state.lang==='zh'?'selected':''}>中文</option></select></div></div></aside></div>`}
function mobileNav(){const unread=(state.sutMessages||[]).filter(n=>!n.read_at&&!n.deleted_at).length;const items=[['home','M3 10.5 12 3l9 7.5V21h-6v-6H9v6H3z','home'],['products','M4 4h7v7H4z M14 4h6v7h-6z M4 14h7v6H4z M14 14h6v6h-6z','products'],['stores','M3 9h18l-2-5H5z M5 11v9h14v-9 M9 20v-6h6v6','stores'],['notifications','M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4','Notifications'],['account','M20 21a8 8 0 0 0-16 0 M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8','account']];return `<nav class="mobile-nav">${items.map(([id,path,k])=>`<button class="${state.route.split('/')[0]===id?'on':''}" onclick="go('${id}')"><b><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}"/></svg>${id==='notifications'&&unread?`<i class="nav-badge">${unread>9?'9+':unread}</i>`:''}</b><span>${id==='notifications'?'Alerts':tr(k)}</span></button>`).join('')}</nav>`}
function foot(){return `<footer class="footer"><div class="foot"><div><img class="footer-logo" src="assets/sut-full-logo.png" alt="Star Universal Trade — Rex International Technologies"><p>Connecting businesses, creating opportunities and helping buyers and sellers connect directly.</p></div><div><b>${tr('about')}</b><a href="#/about">${tr('about')}</a><a href="#/media">${tr('media')}</a><a href="#/contact">${tr('contact')}</a><a href="#/help">${tr('help')}</a></div><div><b>Legal</b><a href="#/privacy">Privacy Policy</a><a href="#/terms">Terms of Service</a></div><div><b>Contact</b><a href="https://wa.me/255666465289" target="_blank" rel="noopener">WhatsApp</a><a href="mailto:Staruniversaltrade@gmail.com">Staruniversaltrade@gmail.com</a><a href="https://instagram.com/Star_universal_trade" target="_blank" rel="noopener">Instagram</a></div></div><div class="bottom"><span>© 2026 Rex International Technologies</span><span>Star Universal Trade</span></div></footer>`}
function card(x){const z=prod(x[0]);if(!z)return '';return `<article class="card"><a href="#/product/${encodeURIComponent(z.id)}"><div class="img"><img src="${esc(z.img)}" alt="${esc(z.title)}"></div></a><div class="body"><div class="tags"><span class="tag">${esc(z.cat)}</span></div><h3>${esc(z.title)}</h3><div class="price">${money(z.price)}</div><div class="meta">${esc(z.seller)} · ${esc(z.loc)}</div><div class="actions2"><a class="btn primary" href="#/product/${encodeURIComponent(z.id)}">View</a><button class="btn" onclick="toggleFav('${esc(z.id)}')">${fav(z.id)?'♥':'♡'}</button><button class="btn" onclick="buyForMe('${esc(z.id)}')">Buy for me</button><button class="btn" onclick="share('${esc(z.id)}')">Share</button></div></div></article>`}
function home(){const cats=[['Electronics','https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=500&q=80'],['Fashion','https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=500&q=80'],['Home & Living','https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=500&q=80'],['Beauty','https://images.unsplash.com/photo-1608248543803-ba4f8c70ae0b?auto=format&fit=crop&w=500&q=80'],['Office','https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=500&q=80'],['Services','https://images.unsplash.com/photo-1521737711867-e3b97375f902?auto=format&fit=crop&w=500&q=80'],['General','https://images.unsplash.com/photo-1472851294608-062f824d29cc?auto=format&fit=crop&w=500&q=80']];return `<main class="wrap"><section class="hero"><div class="hero-main"><div class="ey">STAR UNIVERSAL TRADE</div><h1>Discover products.<br><span style="color:var(--blue)">Connect directly.</span></h1><p>Premium product discovery, seller stores, public requests and direct buyer-seller connection.</p><div class="actions2"><a class="btn primary" href="#/products">${tr('products')}</a><a class="btn" href="#/stores">${tr('stores')}</a><a class="btn" href="#/request" onclick="state.buyForMe=null">Post a Request</a></div></div><aside class="hero-side"><div><div class="ey">For Sellers</div><h2>Build your store on SUT.</h2><p>Create a storefront, publish products and connect with customers.</p><button class="btn primary" onclick="go('seller')">${tr('seller')}</button></div><div class="panel"><b>Public Request</b><p>Tell sellers what you need and let suitable sellers respond.</p><button class="btn" onclick="go('requests')">View requests →</button></div></aside></section><section class="section category-section"><div class="head"><div><div class="ey">Marketplace</div><h2>Shop by category</h2></div><a class="btn" href="#/products">All products</a></div><div class="category-rail">${cats.map(([c,img],i)=>`<button class="category-photo-card" aria-label="Shop ${c}" onclick="setCat('${c}')"><img src="${img}" alt="${c}" loading="lazy"><span class="category-photo-shade"></span><span class="category-photo-title">${c}</span></button>`).join('')}</div></section><section class="section"><div class="head"><div><div class="ey">Featured</div><h2>Popular products</h2></div><a class="btn" href="#/products">View all</a></div><div class="grid">${state.products.length?state.products.slice(0,4).map(card).join(''):'<div class="empty" style="grid-column:1/-1">No published products are available yet.</div>'}</div></section></main>`}
function products(){let q=state.q.toLowerCase();let a=state.products.filter(x=>(!q||x.join(' ').toLowerCase().includes(q))&&(state.cat==='All'||x[2]===state.cat)&&(state.location==='Any location'||x[5]===state.location));return `<main class="wrap"><div class="title"><div><div class="ey">Marketplace</div><h1>${tr('products')}</h1><p>Discover products from independent sellers.</p></div><button class="btn primary" onclick="go('seller')">${tr('seller')}</button></div><div class="bar"><input id="q" class="input" value="${esc(state.q)}" placeholder="Search products, sellers or locations..." onkeydown="if(event.key==='Enter')search()"><button class="btn primary" onclick="search()">Search</button></div><div class="toolbar"><select class="input" onchange="state.cat=this.value;render()"><option>All</option>${['Electronics','Fashion','Home & Living','Beauty','Office','Services','General'].map(c=>`<option ${state.cat===c?'selected':''}>${c}</option>`).join('')}</select><select class="input" onchange="state.location=this.value;render()"><option>Any location</option>${['Dar es Salaam','Arusha','Mwanza','Dodoma','Zanzibar'].map(c=>`<option ${state.location===c?'selected':''}>${c}</option>`).join('')}</select><button class="btn" onclick="go('advanced-search')">Advanced Search</button></div><p>${a.length} products found</p><div class="grid">${a.length?a.map(card).join(''):`<div class="empty" style="grid-column:1/-1">No products matched your search.</div>`}</div></main>`}
function search(){state.q=document.getElementById('q')?.value.trim()||'';render()}
function advancedSearch(){return `<main class="wrap"><div class="title"><div><div class="ey">Discovery</div><h1>Advanced Search</h1><p>Refine products using the available review controls.</p></div></div><div class="panel"><div class="formgrid"><div class="field"><label>Keyword</label><input id="aq" class="input" value="${esc(state.q)}"></div><div class="field"><label>Category</label><select id="ac" class="input"><option>All</option>${['Electronics','Fashion','Home & Living','Beauty','Office','Services','General'].map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label>Location</label><select id="al" class="input"><option>Any location</option>${['Dar es Salaam','Arusha','Mwanza','Dodoma','Zanzibar'].map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label>Availability</label><select class="input"><option>Any availability</option><option>Available</option></select></div></div><div class="actions2"><button class="btn primary" onclick="state.q=document.getElementById('aq').value;state.cat=document.getElementById('ac').value;state.location=document.getElementById('al').value;go('products')">Apply filters</button><button class="btn" onclick="state.q='';state.cat='All';state.location='Any location';go('products')">Clear</button></div></div></main>`}
function product(id){const z=prod(id);if(!z)return `<main class="wrap"><div class="empty"><h2>Product not found</h2><p>This product may be unavailable or the link may be incorrect.</p><a class="btn" href="#/products">Browse products</a></div></main>`;const st=state.stores.find(s=>String(s[0])===String(z.storeId));return `<main class="wrap"><p class="meta"><a href="#/products">${tr('products')}</a> / ${esc(z.title)}</p><section class="detail"><div class="media"><img src="${esc(z.img)}" alt="${esc(z.title)}"></div><div><div class="tags"><span class="tag">${esc(z.cat)}</span><span class="badge">${esc(z.availability)}</span></div><h1>${esc(z.title)}</h1><div class="price" style="font-size:28px">${money(z.price)}</div><div class="panel"><div class="meta">Seller</div><h3>${esc(z.seller)}</h3><div class="meta">${esc(z.loc)}</div><div class="actions2"><button class="btn primary" onclick="contact('${esc(st?.[0]||'')}')">Contact Seller</button>${st?`<a class="btn" href="#/store/${encodeURIComponent(st[0])}">View Store</a>`:''}</div></div><div class="actions2"><button class="btn" onclick="toggleFav('${esc(z.id)}')">${fav(z.id)?'♥ In Wishlist':'♡ Add to Wishlist'}</button><button class="btn" onclick="share('${esc(z.id)}')">Share / Copy Link</button><button class="btn" onclick="go('report/product/${encodeURIComponent(z.id)}')">Report listing</button><button class="btn" onclick="buyForMe('${esc(z.id)}')">Buy for me</button></div></div></section><section class="section layout"><div class="panel"><h2>Product information</h2><div class="list">${[['Category',z.cat],['Location',z.loc],['Availability',z.availability],['Seller',z.seller],['Marketplace model','Direct connection']].map(x=>`<div class="item"><span class="grow">${x[0]}</span><b>${esc(x[1])}</b></div>`).join('')}</div></div><div class="panel"><h3>Need something else?</h3><p>Create a Public Request and let sellers respond.</p><button class="btn primary" onclick="createRequest()">Create request</button></div></section></main>`}
function stores(){return `<main class="wrap"><div class="title"><div><div class="ey">Seller network</div><h1>${tr('stores')}</h1><p>Explore storefronts and seller collections.</p></div><button class="btn primary" onclick="go('seller')">${tr('seller')}</button></div><div class="grid grid3">${state.stores.map(storeCard).join('')}</div></main>`}
function categoryCover(cat){return ({'Electronics':'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=1200&q=85','Fashion':'https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1200&q=85','Home & Living':'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1200&q=85','Beauty':'https://images.unsplash.com/photo-1608248543803-ba4f8c70ae0b?auto=format&fit=crop&w=1200&q=85','Office':'https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1200&q=85','Services':'https://images.unsplash.com/photo-1521737711867-e3b97375f902?auto=format&fit=crop&w=1200&q=85','General':'https://images.unsplash.com/photo-1472851294608-062f824d29cc?auto=format&fit=crop&w=1200&q=85'})[cat]||'https://images.unsplash.com/photo-1472851294608-062f824d29cc?auto=format&fit=crop&w=1200&q=85'}
function storeCard(s){return `<article class="card store"><div class="storecover" style="background-image:linear-gradient(180deg,rgba(4,13,25,.08),rgba(4,13,25,.62)),url('${categoryCover(s[2])}')"><div class="storeavatar">${esc(s[5]||String(s[1]||'S').trim().charAt(0).toUpperCase())}</div></div><div class="body"><span class="badge">Active store</span><h3 style="margin-top:8px">${esc(s[1])}</h3><div class="meta">${esc(s[2]||'General')} · ${esc(s[3]||'')}</div><p>${esc(s[8]||'')}</p><a class="btn" style="display:block;text-align:center" href="#/store/${encodeURIComponent(s[0])}">Visit Store</a><div class="actions2" style="margin-top:8px"><button class="btn" onclick="shareStore('${esc(s[0])}')">Share Store</button><button class="btn" onclick="getStoreQrCode('${esc(s[0])}')">Get Store QR Code</button></div></div></article>`}
function store(id){const s=state.stores.find(x=>String(x[0])===String(id)||String(x[6])===String(id));if(!s)return `<main class="wrap"><div class="empty"><h2>Store not found</h2><p>This store may be unavailable or the link may be incorrect.</p><a class="btn" href="#/stores">Browse stores</a></div></main>`;const items=state.products.filter(x=>String(x[8])===String(s[0]));return `<main class="wrap"><p class="meta"><a href="#/stores">${tr('stores')}</a> / ${esc(s[1])}</p><section class="panel" style="padding:0;overflow:hidden"><div class="storecover" style="height:190px;background-image:linear-gradient(180deg,rgba(4,13,25,.08),rgba(4,13,25,.62)),url('${categoryCover(s[2])}');background-size:cover;background-position:center"><div class="storeavatar" style="width:82px;height:82px;font-size:32px;bottom:-30px">${esc(s[5]||String(s[1]).charAt(0).toUpperCase())}</div></div><div style="padding:45px 22px 22px;display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap"><div><span class="badge">Active store</span><h1 style="font-size:38px;margin:8px 0">${esc(s[1])}</h1><p>${esc(s[8]||'')}</p><p class="meta">${esc(s[2]||'General')} · ${esc(s[3]||'')}</p></div><div class="actions2"><button class="btn primary" onclick="contact('${esc(s[0])}')">Contact Store</button><button class="btn" onclick="shareStore('${esc(s[0])}')">Share Store</button><button class="btn" onclick="getStoreQrCode('${esc(s[0])}')">Get Store QR Code</button><button class="btn" onclick="go('report/store/${encodeURIComponent(s[0])}')">Report Store</button></div></div></section><section class="section"><div class="head"><h2>Store products</h2></div><div class="grid">${items.length?items.map(card).join(''):'<div class="empty" style="grid-column:1/-1">This store has no published products yet.</div>'}</div></section></main>`}
function requests(){return `<main class="wrap"><div class="title"><div><div class="ey">Community demand</div><h1>${tr('requests')}</h1><p>Post what you need and let suitable sellers respond.</p></div><button class="btn primary" onclick="createRequest()">Create Request</button></div><div class="layout"><div class="list">${state.requests.length?state.requests.map(r=>`<article class="panel"><div class="tags"><span class="tag">${esc(r[1])}</span><span class="meta">${esc(r[4])}</span></div><h3>${esc(r[0])}</h3><p>${esc(r[2])} · Budget: ${esc(r[3])}</p>${isSeller()?`<button class="btn primary" onclick="respondToRequest('${esc(r[5]||'')}')">I can help</button>`:''}${state.user&&r[7]===state.user.id?`<button class="btn danger" onclick="closePublicRequest('${esc(r[5]||'')}')">Close Request</button>`:''}</article>`).join(''):'<div class="empty">No open public requests right now.</div>'}</div><aside class="panel"><h3>How it works</h3><div class="list"><div class="item"><b>01</b><span class="grow">Describe what you need.</span></div><div class="item"><b>02</b><span class="grow">Relevant sellers discover it.</span></div><div class="item"><b>03</b><span class="grow">Connect directly.</span></div></div></aside></div></main>`}
function directProductLink(id){return location.href.split('#')[0]+'#/product/'+encodeURIComponent(id)}
function directStoreLink(id){return location.href.split('#')[0]+'#/store/'+encodeURIComponent(id)}
function buyTemplate(z){const u=directProductLink(z.id);return `Please buy this for me: ${z.title}\n\nOpen product: ${u}`}
function createRequest(){state.buyForMe=null;go('request')}
function request(prefill=''){const z=state.buyForMe?prod(state.buyForMe):null;const title=z?.title||prefill||'';const template=z?buyTemplate(z):'';return `<main class="wrap"><div class="title"><div><div class="ey">Buyer tool</div><h1>${z?'Buy for me request':'Create a request'}</h1><p>${z?'Send a sourcing request with the product link.':'Tell sellers exactly what you are looking for.'}</p></div></div>${z?`<section class="panel buy-template"><div class="buy-media"><img src="${z.img}" alt="${esc(z.title)}"></div><div class="buy-copy"><div class="ey">Buy for me</div><h2>${esc(z.title)}</h2><p class="meta">${esc(z.seller)} · ${esc(z.loc)} · ${money(z.price)}</p><label class="template-label">Request template</label><textarea id="buyTemplate" class="template-box" readonly>${esc(template)}</textarea><div class="actions2"><button class="btn" onclick="copyBuyTemplate('${z.id}')">Copy template</button><button class="btn" onclick="share('${z.id}')">Share product link</button></div></div></section>`:''}<div class="layout section"><form class="panel" onsubmit="submitPublicRequest(event)"><div class="formgrid"><div class="field full"><label>What are you looking for?</label><input id="requestTitle" required maxlength="180" value="${esc(title)}" placeholder="e.g. iPhone 15 Pro 256GB"></div><div class="field"><label>Category</label><select id="requestCategory"><option value="">Choose category</option>${['Electronics','Fashion','Home & Living','Beauty','Office','Services'].map(c=>`<option ${z?.cat===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Country</label><input id="requestCountry" value="${esc(z?'Tanzania':'Tanzania')}" maxlength="100"></div><div class="field"><label>City / region</label><input id="requestCity" placeholder="City / region" value="${esc(z?z.loc:'')}" maxlength="100"></div><div class="field"><label>Budget (optional)</label><input id="requestBudget" type="number" min="0" step="0.01" placeholder="e.g. 2500000" value="${z?Number(z.price):''}"></div><div class="field"><label>Currency</label><select id="requestCurrency"><option>TZS</option><option>USD</option><option>EUR</option></select></div><div class="field full"><label>WhatsApp phone number (include country code if outside Tanzania)</label><input id="requestWhatsapp" type="tel" required placeholder="e.g. 0712345678 or +255712345678" maxlength="30"></div><div class="field full"><label>Details</label><textarea id="requestDescription" maxlength="5000" placeholder="Specifications, quantity, condition...">${esc(template)}</textarea></div></div><button class="btn primary" type="submit">Publish Request</button></form><aside class="panel"><h3>Connection marketplace</h3><p>Final product terms, payment and delivery arrangements are agreed directly between buyer and seller.</p><div class="notice">Your request is saved to your SUT account when you are signed in.</div></aside></div></main>`}
async function imageFile(src,name){try{src=new URL(src,document.baseURI).href;const r=await fetch(src,{mode:'cors'});if(!r.ok)throw new Error('image fetch failed');const blob=await r.blob();if(blob.type==='image/png')return new File([blob],name,{type:'image/png'});const bmp=await createImageBitmap(blob);const canvas=document.createElement('canvas');canvas.width=bmp.width;canvas.height=bmp.height;canvas.getContext('2d').drawImage(bmp,0,0);const png=await new Promise(res=>canvas.toBlob(res,'image/png'));return png?new File([png],name,{type:'image/png'}):null}catch(e){return null}}
async function buyForMe(id){const z=prod(id);if(!z)return;const url=directProductLink(id);const text=`Please buy this for me.\n\nProduct: ${z.title}\nSUT product link: ${url}`;try{if(navigator.share){const file=await imageFile(new URL(z.img,location.href).href,`${z.title.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}.png`);if(file&&navigator.canShare?.({files:[file]})){await navigator.share({title:`Buy for me: ${z.title}`,text,files:[file]});return}await navigator.share({title:`Buy for me: ${z.title}`,text});return}}catch(e){if(e?.name==='AbortError')return}window.open('https://wa.me/?text='+encodeURIComponent(text+`\nProduct image: ${new URL(z.img,location.href).href}`),'_blank','noopener')}
function copyBuyTemplate(id){const z=prod(id);const text=buyTemplate(z);copyDirectLink(text,'Buy-for-me template copied')}
function auth(reg=false){return `<main class="auth"><div class="authbox"><div class="auth-brand"><img class="brand-icon large" src="assets/sut-icon.png" alt="SUT"><div class="brand-name"><b><i>STAR</i> <em>UNIVERSAL</em> <i>TRADE</i></b><small>Rex International Technologies</small></div></div><h2 style="margin-top:24px">${reg?'Create your account':'Welcome back'}</h2><p>${reg?'Start as a buyer and later activate seller mode.':'Sign in to continue to your SUT account.'}</p>${!reg?'<button class="google-btn" type="button" onclick="signInWithGoogle()"><span>G</span> Continue with Google</button><div class="or"><span>or continue with email</span></div>':''}<form onsubmit="submitAuth(event,${reg})">${reg?'<div class="field"><label>Full name</label><input id="name" autocomplete="name" required></div>':''}<div class="field"><label>Email</label><input id="email" type="email" autocomplete="email" required placeholder="you@example.com"></div><div class="field"><label>Password</label><input id="password" type="password" autocomplete="${reg?'new-password':'current-password'}" minlength="6" required placeholder="At least 6 characters"></div><button class="btn primary" style="width:100%">${reg?'Create Account':'Sign in'}</button></form><div class="notice" style="margin-top:13px">Secure account access is provided by Supabase Auth. Never share your password with anyone.</div><p style="text-align:center"><a style="color:var(--blue)" href="#/${reg?'login':'register'}">${reg?'Already registered? Sign in':'Create an account'}</a></p></div></main>`}
function account(){if(!state.user)return `<main class="auth"><div class="authbox"><div class="ey">Account</div><h2>Sign in to your SUT account</h2><p>Access wishlist, notifications, seller tools and settings.</p><button class="btn primary" style="width:100%" onclick="go('login')">Sign in</button><button class="btn" style="width:100%;margin-top:8px" onclick="go('register')">Create account</button></div></main>`;return `<main class="wrap"><div class="title"><div><div class="ey">Account Center</div><h1>Hello, ${esc(state.user.name)}</h1><p>${esc(state.user.email)} · ${state.user.role}</p></div><button class="btn danger" onclick="signOut()">Sign out</button></div><div class="grid grid3"><button class="card" style="padding:20px;text-align:left;color:var(--text)" onclick="go('wishlist')"><div class="ey">${tr('wishlist')}</div><h3>Saved products</h3><p>Open wishlist →</p></button><button class="card" style="padding:20px;text-align:left;color:var(--text)" onclick="go('notifications')"><div class="ey">Notifications</div><h3>Updates and activity</h3><p>Open notifications →</p></button>${isSeller()?'<button class="card" style="padding:20px;text-align:left;color:var(--text)" onclick="go(\'seller-dashboard\')"><div class="ey">My Store</div><h3>Store Dashboard</h3><p>Manage products →</p></button>':'<button class="card" style="padding:20px;text-align:left;color:var(--text)" onclick="go(\'seller\')"><div class="ey">Become a Seller</div><h3>Create your store</h3><p>Activate seller mode →</p></button>'}<button class="card" style="padding:20px;text-align:left;color:var(--text)" onclick="go('settings')"><div class="ey">${tr('settings')}</div><h3>Account & appearance</h3><p>Open settings →</p></button><button class="card" style="padding:20px;text-align:left;color:var(--text)" onclick="go('help')"><div class="ey">${tr('help')}</div><h3>Guides and support</h3><p>Open Help Centre →</p></button><button class="card" style="padding:20px;text-align:left;color:var(--text)" onclick="changeRole()"><div class="ey">Change account</div><h3>${isSeller()?'Buyer mode':'Seller activation'}</h3><p>${isSeller()?'Buyer and seller features':'Become a seller'} →</p></button></div></main>`}
async function signOut(){if(!window.sutSupabase){toast('Supabase is not configured');return}const {error}=await window.sutSupabase.auth.signOut();if(error){toast(error.message);return}state.user=null;go('home');render()}
function changeRole(){if(!state.user)return go('login');if(isSeller()){toast('Seller permissions are controlled by the database; buyer view is not a security role change.');return}go('seller')}
function seller(){if(!state.user)return `<main class="auth"><div class="authbox"><h2>Sign in to become a seller</h2><p>Use your existing buyer account. You do not need a second account.</p><button class="btn primary" onclick="go('login')">Sign in</button></div></main>`;if(state.myStore)return `<main class="wrap"><section class="panel"><h2>Your store is already connected</h2><p>${esc(state.myStore.store_name)}</p><button class="btn primary" onclick="go('seller-dashboard')">Open Store Dashboard</button></section></main>`;return `<main class="wrap"><div class="title"><div><div class="ey">Seller onboarding</div><h1>${tr('seller')}</h1><p>Create your storefront using your existing SUT account.</p></div></div><div class="layout"><form class="panel" onsubmit="createSellerStore(event)"><div class="notice success">One account can be used as both buyer and seller. Store ownership is linked to your signed-in account.</div><div class="formgrid" style="margin-top:14px"><div class="field full"><label>Store name</label><input id="storeName" required maxlength="100" placeholder="Your store name"></div><div class="field"><label>Primary category</label><select id="storeCategory" required><option value="">Choose category</option><option>Electronics</option><option>Fashion</option><option>Home & Living</option><option>Beauty</option><option>Office</option><option>Services</option><option>General</option></select></div><div class="field"><label>Country</label><input id="storeCountry" value="Tanzania" maxlength="100" required></div><div class="field"><label>City</label><input id="storeCity" placeholder="Dar es Salaam" maxlength="100" required></div><div class="field"><label>Country calling code</label><select id="storeCountryCode" class="input" onchange="applyCountryCode()"><option value="255">Tanzania (+255)</option><option value="254">Kenya (+254)</option><option value="256">Uganda (+256)</option><option value="250">Rwanda (+250)</option><option value="257">Burundi (+257)</option><option value="1">United States/Canada (+1)</option><option value="44">United Kingdom (+44)</option><option value="91">India (+91)</option><option value="971">UAE (+971)</option></select><label>WhatsApp phone number</label><input id="storeContact" type="tel" inputmode="tel" autocomplete="tel-national" placeholder="e.g. 0712 345 678" maxlength="30" required><small class="meta">Choose the country; SUT builds the WhatsApp link automatically.</small></div><div class="field full"><label>Store description</label><textarea id="storeDescription" maxlength="3000" placeholder="Tell buyers what your store offers."></textarea></div></div><button class="btn primary" type="submit">Create Seller Profile</button></form><aside class="panel"><h3>Seller journey</h3><div class="list"><div class="item"><b>01</b><span class="grow">Create store identity.</span></div><div class="item"><b>02</b><span class="grow">Add products and media.</span></div><div class="item"><b>03</b><span class="grow">Connect with buyers.</span></div></div></aside></div></main>`}
function dashboard(){if(!isSeller())return `<main class="auth"><div class="authbox"><h2>Seller access</h2><p>Create a store to access seller tools.</p><button class="btn primary" onclick="go('seller')">Become a Seller</button></div></main>`;const st=state.myStore;const mine=state.products.filter(x=>String(x[8])===String(st?.id));return `<main class="wrap"><div class="title"><div><div class="ey">Seller workspace</div><h1>Store Dashboard</h1><p>Manage your storefront and catalogue.</p></div><button class="btn primary" onclick="go('upload')">+ Add Product</button></div><div class="kpis"><div class="kpi"><b>${mine.length}</b><span>Published products</span></div><div class="kpi"><b>${esc(st?.status||'active')}</b><span>Store status</span></div></div><div class="layout section"><div class="panel"><div class="head"><h3>Store overview</h3><button class="btn" onclick="go('store/${encodeURIComponent(st?.slug||st?.id||'')}')">View public store</button></div><div class="item"><div class="avatar">${esc((st?.store_name||'S').trim().charAt(0).toUpperCase())}</div><span class="grow"><b>${esc(st?.store_name||'Your Store')}</b><small class="meta">${esc(st?.city||st?.country||'Location')}</small><small>${esc(st?.description||'')}</small></span><span class="badge">${esc(st?.status||'active')}</span></div><div class="actions2"><button class="btn primary" onclick="shareStore('${esc(st?.id||'')}')">Share Store</button><button class="btn" onclick="getStoreQrCode('${esc(st?.id||'')}')">Get Store QR Code</button></div></div><div class="panel"><h3>Quick actions</h3><div class="list"><button class="btn" onclick="go('upload')">Upload Product</button><button class="btn" onclick="loadMyProducts(true)">Refresh My Products</button><button class="btn" onclick="editStoreContact()">Edit WhatsApp Contact</button><button class="btn" onclick="go('notifications')">Notifications</button></div></div></div><section class="section"><div class="head"><h2>Manage my products</h2></div><div class="grid">${mine.length?mine.map(x=>{const z=prod(x[0]);return z?`<article class="card"><a href="#/product/${encodeURIComponent(z.id)}"><div class="img"><img src="${esc(z.img)}" alt="${esc(z.title)}"></div></a><div class="body"><h3>${esc(z.title)}</h3><div class="price">${money(z.price)}</div><div class="meta">${esc(z.availability)}</div><div class="actions2"><button class="btn" onclick="editProduct('${esc(z.id)}')">Edit</button><button class="btn danger" onclick="archiveProduct('${esc(z.id)}')">Unpublish</button><button class="btn" onclick="share('${esc(z.id)}')">Share</button></div></div></article>`:''}).join(''):'<div class="empty" style="grid-column:1/-1">You have no published products yet.</div>'}</div></section></main>`}
function upload(){if(!isSeller())return dashboard();return `<main class="wrap"><div class="title"><div><div class="ey">Seller workspace</div><h1>Add Product</h1><p>Product information and image upload.</p></div></div><form class="layout" onsubmit="createProduct(event)"><div class="panel"><div class="drop" onclick="document.getElementById('files').click()"><div style="font-size:38px;color:var(--blue)">＋</div><h3>Upload product images</h3><p>Select up to 5 product images. Images are uploaded to the configured Cloudinary unsigned preset.</p><button type="button" class="btn">Choose images</button><input id="files" type="file" accept="image/jpeg,image/png,image/webp,image/avif" multiple hidden onchange="preview(event)"></div><div id="pre" class="previews"></div><div class="notice" style="margin-top:13px">A product is saved as a draft first and published only after the image upload and database writes succeed.</div></div><div class="panel"><div class="formgrid"><div class="field full"><label>Product title</label><input id="productTitle" required maxlength="180" placeholder="Premium Wireless Headphones"></div><div class="field"><label>Category</label><select id="productCategory"><option value="">General / no category</option>${['Electronics','Fashion','Home & Living','Beauty','Office','Services','General'].map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label>Price</label><input id="productPrice" type="number" min="0.01" step="0.01" required placeholder="0"></div><div class="field"><label>Currency</label><select id="productCurrency"><option>TZS</option><option>USD</option><option>EUR</option></select></div><div class="field"><label>Availability</label><select id="productAvailability"><option value="available">Available</option><option value="out_of_stock">Out of stock</option><option value="on_request">On request</option></select></div><div class="field"><label>Country</label><input id="productCountry" value="Tanzania" maxlength="100"></div><div class="field"><label>City</label><input id="productCity" value="${esc(state.myStore?.city||'')}" maxlength="100"></div><div class="field full"><label>Description</label><textarea id="productDescription" required maxlength="5000" placeholder="Specifications, condition, availability..."></textarea></div></div><button class="btn primary" type="submit">Save and Publish Product</button></div></form></main>`}
function preview(e){const o=document.getElementById('pre');o.innerHTML='';[...e.target.files].filter(f=>f.type.startsWith('image/')).slice(0,5).forEach(f=>{const r=new FileReader();r.onload=()=>{const d=document.createElement('div');d.className='thumb';d.innerHTML=`<img src="${r.result}" alt=""><span>${(f.size/1048576).toFixed(1)}MB</span>`;o.append(d)};r.readAsDataURL(f)});if([...e.target.files].some(f=>!f.type.startsWith('image/')))toast('Images only. Video files are not supported.')}
function wishlist(){const a=state.products.filter(x=>fav(x[0]));return `<main class="wrap"><div class="title"><div><div class="ey">Saved</div><h1>${tr('wishlist')}</h1><p>Keep products you want to revisit.</p></div></div><div class="grid">${a.length?a.map(card).join(''):`<div class="empty" style="grid-column:1/-1">Your wishlist is empty. <a style="color:var(--blue)" href="#/products">Explore products →</a></div>`}</div></main>`}
function notifications(){const key='sut_local_notifications';const items=JSON.parse(localStorage.getItem(key)||'[]');if(state.user&&!state.sutMessagesLoaded&&!state.sutMessagesLoading)loadInAppMessages();const live=(state.sutMessages||[]).filter(n=>!n.deleted_at);return `<main class="wrap"><div class="title"><div><div class="ey">Account</div><h1>Notifications</h1><p>In-app announcements and marketplace updates.</p></div><button class="btn" onclick="loadInAppMessages(true)">Refresh</button></div><div class="list">${live.map(n=>`<div class="item"><div class="avatar">${n.read_at?'•':'●'}</div><div class="grow"><b>${esc(n.title||'SUT Announcement')}</b><p>${esc(n.body||'')}</p><small class="meta">${esc(n.created_at?new Date(n.created_at).toLocaleString():'')}</small></div><span class="badge">${n.read_at?'Read':'New'}</span>${!n.read_at?`<button class="btn" onclick="markInAppRead('${esc(n.id)}')">Mark read</button>`:''}<button class="btn danger" onclick="deleteInAppNotification('${esc(n.id)}')">Delete</button></div>`).join('')}${items.map((n,i)=>`<div class="item"><div class="avatar">${n.read?'•':'●'}</div><div class="grow"><b>${esc(n.title)}</b><p>${esc(n.body)}</p><small class="meta">${esc(n.time||'')}</small></div><span class="badge">${n.read?'Read':'New'}</span><button class="btn danger" onclick="deleteNotification('${esc(n.id||i)}')">Delete</button></div>`).join('')}${!live.length&&!items.length?'<div class="empty">No notifications yet.</div>':''}</div></main>`}
function clearNotifications(){localStorage.removeItem('sut_local_notifications');render()}
function deleteNotification(id){const a=JSON.parse(localStorage.getItem('sut_local_notifications')||'[]');const i=Number.isInteger(Number(id))?Number(id):-1;if(i>=0&&i<a.length)a.splice(i,1);else{const j=a.findIndex(n=>String(n.id)===String(id));if(j>=0)a.splice(j,1)}localStorage.setItem('sut_local_notifications',JSON.stringify(a));render()}
async function deleteInAppNotification(id){if(!state.user||!window.sutSupabase)return;const {error}=await window.sutSupabase.from('sut_messages').update({deleted_at:new Date().toISOString()}).eq('id',id).eq('recipient_id',state.user.id);if(error){toast('Could not delete notification: '+error.message+' — apply the included notification migration first.');return}state.sutMessages=(state.sutMessages||[]).map(n=>String(n.id)===String(id)?{...n,deleted_at:new Date().toISOString()}:n);toast('Notification deleted from your inbox');render()}

function settings(){return `<main class="wrap"><div class="title"><div><div class="ey">Account Center</div><h1>${tr('settings')}</h1><p>Manage account preferences and appearance.</p></div></div><div class="layout"><div class="panel"><h3>Preferences</h3><div class="list"><div class="item"><div class="grow"><b>Language</b><p>English · Swahili · French · Arabic · Chinese</p></div><select class="input" style="max-width:150px" onchange="setLang(this.value)"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="sw" ${state.lang==='sw'?'selected':''}>Swahili</option><option value="fr" ${state.lang==='fr'?'selected':''}>Français</option><option value="ar" ${state.lang==='ar'?'selected':''}>العربية</option><option value="zh" ${state.lang==='zh'?'selected':''}>中文</option></select></div><div class="item"><div class="grow"><b>Appearance</b><p>Light / Dark mode</p></div><button class="btn" onclick="toggleTheme()">${state.theme==='light'?'Dark mode':'Light mode'}</button></div><div class="item"><div class="grow"><b>Notifications</b><p>Email / in-app notifications</p></div><button class="btn" onclick="toast('Notification preferences are ready for integration')">Change</button></div><div class="item"><div class="grow"><b>Privacy</b><p>Visibility and data controls</p></div><button class="btn" onclick="go('privacy')">View policy</button></div></div></div><div class="panel"><h3>Account & security</h3><div class="list"><div class="item"><div class="grow"><b>Email</b><p>${esc(state.user?.email||'Not signed in')}</p></div><span class="badge">Auth</span></div><div class="item"><div class="grow"><b>Sessions</b><p>Manage signed-in devices.</p></div><button class="btn" onclick="toast('Supabase Auth will manage sessions later')">Manage</button></div><div class="item"><div class="grow"><b>Terms</b><p>Review the rules for using SUT.</p></div><button class="btn" onclick="go('terms')">View terms</button></div></div></div></div></main>`}
function about(){return simple('About SUT','Rex International Technologies',`<h2>Star Universal Trade</h2><p>Star Universal Trade (SUT) is a connection marketplace focused on product discovery, seller storefronts, public requests and direct buyer-seller communication.</p><h3>Connection-first model</h3><p>SUT currently focuses on connecting buyers and sellers. Payment and delivery are handled directly between the parties outside the platform unless a future service explicitly states otherwise.</p><h3>Company</h3><p>SUT is operated under <b>Rex International Technologies</b>.</p>`)}
function media(){return simple('Media','Brand & media',`<p>This area is reserved for official SUT media, announcements and brand content.</p><div class="panel"><h3>Official channels</h3><p>Use the official SUT Instagram and future authorized media channels to explore company updates.</p><a class="btn primary" href="https://instagram.com/Star_universal_trade" target="_blank" rel="noopener">Open Instagram</a></div>`)}
function contactPage(){return simple('Contact','Star Universal Trade',`<p>Connect with SUT through the official channels below.</p><div class="list"><div class="item"><span class="grow"><b>WhatsApp</b><p>Direct contact channel</p></span><a class="btn" href="https://wa.me/255666465289" target="_blank" rel="noopener">Open</a></div><div class="item"><span class="grow"><b>Email</b><p>Staruniversaltrade@gmail.com</p></span><a class="btn" href="mailto:Staruniversaltrade@gmail.com">Email</a></div><div class="item"><span class="grow"><b>Instagram</b><p>Star_universal_trade</p></span><a class="btn" href="https://instagram.com/Star_universal_trade" target="_blank" rel="noopener">Open</a></div></div>`)}
function simple(t,e,b){return `<main class="wrap"><div class="title"><div><div class="ey">${e}</div><h1>${t}</h1></div></div><div class="panel legal" style="max-width:980px">${b}</div></main>`}
const legalIntro='<div class="legal-head"><img src="assets/sut-icon.png" alt="SUT"><div><strong>Star Universal Trade (SUT)</strong><span>Rex International Technologies</span></div></div>';
function privacy(){return simple('Privacy Policy','Legal',`${legalIntro}<p class="legal-updated"><b>Effective date:</b> To be confirmed before public launch</p><h2>Your privacy matters</h2><p>This Privacy Policy explains, in professional web form, the privacy principles contained in the policy notes supplied for SUT.</p><h3>1. Information we may collect</h3><ul><li>Account information such as name, email address, phone/contact information and account credentials.</li><li>Marketplace information you submit, including products, stores, public requests and other content.</li><li>Technical and usage information needed to operate, secure and improve the service.</li><li>Location information that you choose to provide for products, stores or requests.</li></ul><h3>2. How information is used</h3><p>Information may be used to create and manage accounts, display products and stores, connect buyers and sellers, process requests, provide notifications, maintain security, improve the platform and communicate service information.</p><h3>3. Location</h3><p>Where location is used, it is intended to support relevant marketplace experiences such as showing location information associated with products, stores or requests. Users can choose what location information they provide where the feature permits.</p><h3>4. Cookies and similar technologies</h3><p>SUT may use cookies or local/browser storage where technically necessary for preferences, sessions, security or user experience. Browser settings may provide controls over cookies.</p><h3>5. Third-party services</h3><p>SUT may use third-party providers required to operate the platform. The planned production architecture includes Supabase for authentication/database services and Cloudinary for product media. Google may provide authentication where enabled. External services such as WhatsApp have their own privacy practices.</p><h3>6. Data sharing and security</h3><p>We do not intend to sell personal information. Information may be shared with service providers when necessary to operate SUT, comply with law, protect users or fulfill a requested service. Reasonable technical and organizational safeguards are intended to protect information, although no online system can guarantee absolute security.</p><h3>7. Your rights</h3><p>Subject to applicable requirements, users may request access to, correction of, or deletion of personal information associated with their account and may ask questions about its use.</p><h3>8. Retention</h3><p>Information may be retained as reasonably necessary to operate the service, maintain records, resolve disputes, comply with legal obligations and protect the platform.</p><h3>9. Changes</h3><p>This policy may be updated when SUT, its technology or legal requirements change. The updated policy will be published on this page with an updated effective date where appropriate.</p><h3>10. Contact</h3><p>Privacy questions can be sent to <a href="mailto:Staruniversaltrade@gmail.com">Staruniversaltrade@gmail.com</a>, through <a href="https://wa.me/255666465289" target="_blank" rel="noopener">WhatsApp</a>, or the official Instagram account.</p>`)}
function terms(){return simple('Terms of Service','Legal',`${legalIntro}<p class="legal-updated"><b>Effective date:</b> To be confirmed before public launch</p><h2>Welcome to Star Universal Trade</h2><p>By accessing or using SUT, you agree to use the platform responsibly and in accordance with these Terms.</p><h3>1. Account and registration</h3><p>Some SUT features require an account. You are responsible for accurate information, account security and activity performed through your account. One account may begin as a buyer account and may later be activated for seller use.</p><h3>2. Prohibited conduct</h3><p>You must not use SUT for unlawful, fraudulent, deceptive, abusive or harmful activity. You must not impersonate others, interfere with the platform, misuse another user's information, or publish content that violates applicable law or the rights of others.</p><h3>3. User content and product information</h3><p>Users and sellers are responsible for content they submit, including descriptions, photographs, videos and product information. You must have the necessary rights and permissions for material you upload. SUT may restrict or remove content that violates these Terms or creates a serious risk.</p><h3>4. Media and videos</h3><p>Product photos and videos must be lawful and appropriate for the platform. Where third-party or social media content is connected, the user or seller must have the necessary permission or rights to use or link that content.</p><h3>5. Connection marketplace and transactions</h3><p>SUT is a connection marketplace. Unless a future service expressly states otherwise, <b>payment and delivery are arranged directly between buyers and sellers outside SUT</b>. SUT does not currently act as the payment processor or delivery provider for marketplace transactions. Users should independently evaluate counterparties, products, prices, payment arrangements and delivery terms.</p><h3>6. Intellectual property</h3><p>The SUT name, branding, interface and platform materials are protected by applicable rights. Do not copy, reproduce or misuse SUT or third-party intellectual property without permission.</p><h3>7. Account suspension and termination</h3><p>SUT may restrict, suspend or terminate access where reasonably necessary for security, legal compliance, serious violations or protection of the platform and its users.</p><h3>8. Availability and liability</h3><p>We aim to provide a reliable service but cannot guarantee uninterrupted or error-free availability. To the extent permitted by law, SUT and Rex International Technologies are not responsible for losses arising from transactions, payment or delivery arrangements, user conduct, external services or information supplied by users.</p><h3>9. Changes to these Terms</h3><p>Terms may be updated as the platform develops. Updated terms will be published on the platform and continued use may constitute acceptance where permitted by law.</p><h3>10. Company and contact</h3><p>Star Universal Trade is operated under <b>Rex International Technologies</b>. Questions about these Terms can be sent to <a href="mailto:Staruniversaltrade@gmail.com">Staruniversaltrade@gmail.com</a>, <a href="https://wa.me/255666465289" target="_blank" rel="noopener">WhatsApp</a>, or the official Instagram account.</p>`)}
function help(){return simple('Help Centre','Support',`<h2>Using Star Universal Trade</h2><h3>Getting started</h3><ol><li>Explore products, categories and seller stores.</li><li>Open a product to view its details and seller information.</li><li>Use direct contact options to connect with sellers.</li><li>Create an account when you need account-specific features.</li></ol><h3>For buyers</h3><p>Search products, use categories and advanced search, save products to your wishlist, share product links, create a Public Request, and use <b>Buy for me</b> to request help sourcing a product.</p><h3>For sellers</h3><p>Activate seller mode, create your store, open Store Dashboard, manage products and publish product media and manage listings.</p><h3>Requests and communication</h3><p>Public Requests help buyers describe what they need so suitable sellers can respond. Payment and delivery are currently handled outside SUT by agreement between the parties.</p><h3>Language and appearance</h3><p>SUT includes English, Swahili, French, Arabic and Chinese language controls plus Light/Dark mode.</p><h3>Need more help?</h3><p>Contact SUT through <a href="mailto:Staruniversaltrade@gmail.com">Staruniversaltrade@gmail.com</a> or WhatsApp.</p>`)}
function admin(){if(!isAdmin())return `<main class="auth"><div class="authbox"><h2>Admin access</h2><p>This area is restricted to approved administrator accounts.</p><button class="btn" onclick="go('account')">Back to Account</button></div></main>`;if(sessionStorage.getItem('sut_admin_reauth')!=='1')return `<main class="auth"><div class="authbox"><h2>Admin verification</h2><p>Enter your account password to re-verify before opening administration tools.</p><form onsubmit="submitAdminGate(event)"><div class="field"><label>Account password</label><input id="adminPassword" type="password" autocomplete="current-password" required></div><button class="btn primary" type="submit">Verify and Continue</button></form><p class="meta">Google-only accounts need password re-verification configured to use this gate.</p></div></main>`;const a=state.backendStats||{};return `<main class="wrap"><div class="title"><div><div class="ey">Administration</div><h1>Admin Console</h1><p>Moderation tools and recipient-based communications.</p></div><button class="btn primary" onclick="loadAdminStats(true)">Refresh</button></div><div class="kpis"><div class="kpi"><b>${a.users??'—'}</b><span>Profiles</span></div><div class="kpi"><b>${a.stores??'—'}</b><span>Stores</span></div><div class="kpi"><b>${a.products??'—'}</b><span>Products</span></div><div class="kpi"><b>${a.requests??'—'}</b><span>Public requests</span></div><div class="kpi"><b>${a.reports??'—'}</b><span>Reports</span></div><div class="kpi"><b>${a.categories??'—'}</b><span>Categories</span></div></div><section class="panel section"><h2>Live analytics overview</h2><p>Counts are read from Supabase. N/A means the current role cannot read the table.</p><div class="list">${[['Registered profiles',a.users],['Stores',a.stores],['Products',a.products],['Public requests',a.requests],['Reports',a.reports],['Categories',a.categories]].map(([label,value])=>`<div class="item"><span class="grow">${label}</span><b>${value??'—'}</b></div>`).join('')}</div></section><div class="grid grid3 section"><button class="card" style="padding:20px;text-align:left;color:var(--text)" onclick="loadAdminQueue('products')"><h3>Product moderation</h3><p>Review and unpublish problematic listings.</p></button><button class="card" style="padding:20px;text-align:left;color:var(--text)" onclick="loadAdminQueue('stores')"><h3>Store management</h3><p>Review stores and suspend or reactivate.</p></button><button class="card" style="padding:20px;text-align:left;color:var(--text)" onclick="loadAdminQueue('reports')"><h3>Reports</h3><p>Review submitted reports.</p></button></div><section class="panel section"><h2>Communication centre</h2><p>Load recipient records from Supabase, then select a recipient. “All users/stores” creates a reviewable recipient list; WhatsApp/email are opened for user confirmation, not falsely reported as delivered.</p><form onsubmit="adminCompose(event)"><div class="formgrid"><div class="field"><label>Audience</label><select id="adminRecipientType" onchange="loadAdminRecipients()"><option value="all">All Users</option><option value="sellers">Sellers Only</option><option value="buyers">Buyers Only</option><option value="stores">All Stores</option><option value="one">Select Individually</option></select></div><div class="field"><label>Search recipients</label><input id="adminRecipientSearch" oninput="filterAdminRecipients()" placeholder="Name, email, phone or store"></div><div class="field full"><button class="btn" type="button" onclick="loadAdminRecipients()">Load / refresh recipients</button><span id="adminRecipientStatus" class="meta">Load recipient records to begin.</span></div><div class="field full"><label>Recipients (select one or more)</label><select id="adminRecipientList" multiple size="5" style="min-height:130px;width:100%" onchange="syncAdminRecipient()"></select></div><div class="field"><label>WhatsApp phone</label><input id="adminRecipientPhone" type="tel" placeholder="Selected recipient contact"></div><div class="field"><label>Email address</label><input id="adminRecipientEmail" type="email" placeholder="Selected recipient email"></div><div class="field full"><label>Message / warning</label><textarea id="adminMessage" required maxlength="2000" placeholder="Write a clear announcement or seller warning"></textarea></div></div><div class="actions2"><button class="btn" type="button" onclick="adminSendWhatsApp()">Open WhatsApp</button><button class="btn" type="button" onclick="adminSendEmail()">Open Email</button><button class="btn primary" type="submit">Save in-app draft</button></div><p class="meta">WhatsApp and email require pressing Send in the external app. In-app delivery depends on a compatible messages table and RLS policies; this action reports errors honestly.</p></form></section><section class="panel section" id="adminQueue"><h3>Management workspace</h3><p>Select a management area above to load live records.</p></section><button class="btn" onclick="sessionStorage.removeItem('sut_admin_reauth');render()">Lock Admin Console</button></main>`}
let adminRecipientCache=[];
async function loadAdminRecipients(){if(!isAdmin()||sessionStorage.getItem('sut_admin_reauth')!=='1')return;const sb=window.sutSupabase,type=document.getElementById('adminRecipientType')?.value||'all',status=document.getElementById('adminRecipientStatus'),list=document.getElementById('adminRecipientList');if(!sb||!list)return;status.textContent='Loading records from Supabase…';adminRecipientCache=[];try{if(type==='stores'){const {data,error}=await sb.from('stores').select('*').limit(1000);if(error)throw error;(data||[]).forEach(r=>adminRecipientCache.push({id:r.owner_id||r.id,name:r.store_name||r.name||'Store',email:r.email||'',phone:r.contact_url||r.whatsapp||r.phone||'',kind:'Store'}))}if(['one','all','sellers','buyers'].includes(type)){const {data,error}=await sb.from('profiles').select('*').limit(1000);if(error)throw error;let profiles=data||[];if(type==='sellers'||type==='buyers'){const roleName=type==='sellers'?'seller':'buyer';const {data:roles,error:roleError}=await sb.from('user_roles').select('user_id,role').eq('role',roleName).limit(2000);if(roleError)throw new Error('Could not resolve '+type+' audience from user_roles: '+roleError.message);const ids=new Set((roles||[]).map(r=>String(r.user_id)));profiles=profiles.filter(r=>ids.has(String(r.id)));}profiles.forEach(r=>adminRecipientCache.push({id:r.id,name:r.full_name||r.name||r.username||'User',email:r.email||'',phone:r.phone||r.whatsapp||r.phone_number||'',kind:'User'}))}adminRecipientCache=adminRecipientCache.filter((r,i,a)=>r.id&&a.findIndex(x=>String(x.id)===String(r.id)&&x.kind===r.kind)===i);filterAdminRecipients();status.textContent=`Loaded ${adminRecipientCache.length} recipient record(s). Select records below.`}catch(e){status.textContent='Could not load recipient records: '+e.message;toast('Recipient lookup failed; check Supabase table access and RLS.')}}
function filterAdminRecipients(){const list=document.getElementById('adminRecipientList');if(!list)return;const q=(document.getElementById('adminRecipientSearch')?.value||'').trim().toLowerCase();const matches=adminRecipientCache.filter(r=>[r.name,r.email,r.phone,r.kind].join(' ').toLowerCase().includes(q));list.innerHTML=matches.map(r=>`<option value="${esc(r.kind+'|'+r.id)}">${esc(r.kind+' · '+r.name+' · '+(r.email||r.phone||'no contact'))}</option>`).join('');const status=document.getElementById('adminRecipientStatus');if(status&&q&&!matches.length)status.textContent=`No users or stores match “${q}”.`;else if(status&&q)status.textContent=`${matches.length} matching recipient(s).`}
function syncAdminRecipient(){const list=document.getElementById('adminRecipientList');const selected=[...(list?.selectedOptions||[])].map(o=>adminRecipientCache.find(r=>o.value===r.kind+'|'+r.id)).filter(Boolean);const phone=document.getElementById('adminRecipientPhone'),email=document.getElementById('adminRecipientEmail');if(selected.length===1){phone.value=String(selected[0].phone||'').replace(/^https?:\/\/(?:wa\.me|api\.whatsapp\.com)\//i,'');email.value=selected[0].email||''}else{phone.value='';email.value=''}if(selected.length>1)toast(`${selected.length} recipients selected; external apps may need to be opened separately.`)}

async function submitAdminGate(event){event.preventDefault();if(!isAdmin()||!window.sutSupabase)return;const password=document.getElementById('adminPassword')?.value;if(!password)return;const {data,error}=await window.sutSupabase.auth.signInWithPassword({email:state.user.email,password});if(error||!data?.user){toast('Password verification failed');return}sessionStorage.setItem('sut_admin_reauth','1');await loadSUTUser(data.user);await loadAdminStats(false);render()}
async function editProduct(id){if(!requireSignedIn()||!state.myStore)return;const z=prod(id);if(!z)return;const title=prompt('Product title',z.title);if(title===null)return;const priceText=prompt('Price',String(z.price));if(priceText===null)return;const price=Number(priceText);if(!title.trim()||!Number.isFinite(price)||price<=0){toast('Enter a valid title and price');return}const {error}=await window.sutSupabase.from('products').update({title:title.trim(),price,updated_at:new Date().toISOString()}).eq('id',id).eq('store_id',state.myStore.id);if(error){toast('Could not update product: '+error.message);return}toast('Product updated');await loadSUTCatalog();render()}
async function archiveProduct(id){if(!requireSignedIn()||!state.myStore)return;if(!confirm('Unpublish this product? It will no longer be visible publicly.'))return;const {error}=await window.sutSupabase.from('products').update({status:'archived',updated_at:new Date().toISOString()}).eq('id',id).eq('store_id',state.myStore.id);if(error){toast('Could not unpublish product: '+error.message);return}toast('Product unpublished');await loadSUTCatalog();render()}
async function editStoreContact(){if(!requireSignedIn()||!state.myStore)return;const number=prompt('Enter WhatsApp phone number with country code if outside Tanzania',state.myStore.contact_url||'');if(number===null)return;let contact_url;try{contact_url=normalizeContact(number)}catch(e){toast(e.message);return}const {data,error}=await window.sutSupabase.from('stores').update({contact_url}).eq('id',state.myStore.id).eq('owner_id',state.user.id).select('id,owner_id,store_name,slug,description,country,city,contact_url,status,category_name').single();if(error){toast('Could not update contact: '+error.message);return}state.myStore=data;await loadSUTCatalog();toast('WhatsApp contact updated');render()}
async function loadInAppMessages(force=false){if(!state.user||!window.sutSupabase||state.sutMessagesLoading)return;state.sutMessagesLoading=true;try{const {data,error}=await window.sutSupabase.from('sut_messages').select('id,title,body,created_at,read_at,deleted_at').eq('recipient_id',state.user.id).is('deleted_at',null).order('created_at',{ascending:false}).limit(100);if(error)throw error;state.sutMessages=data||[];state.sutMessagesLoaded=true;if(state.route.split('/')[0]==='notifications'){const unread=state.sutMessages.filter(m=>!m.read_at).map(m=>m.id);if(unread.length){const stamp=new Date().toISOString();const {error:readErr}=await window.sutSupabase.from('sut_messages').update({read_at:stamp}).in('id',unread).eq('recipient_id',state.user.id);if(!readErr)state.sutMessages=state.sutMessages.map(m=>unread.includes(m.id)?{...m,read_at:stamp}:m);else console.warn('SUT mark inbox read:',readErr.message)}}if(force)toast(`Loaded ${state.sutMessages.length} in-app message(s)`)}catch(e){console.warn('SUT in-app inbox:',e.message);if(force)toast('Could not load in-app messages: '+e.message)}finally{state.sutMessagesLoading=false;if(state.route.split('/')[0]==='notifications')render()}}
async function markInAppRead(id){if(!state.user||!window.sutSupabase)return;const {error}=await window.sutSupabase.from('sut_messages').update({read_at:new Date().toISOString()}).eq('id',id).eq('recipient_id',state.user.id);if(error){toast('Could not mark message read: '+error.message);return}state.sutMessages=state.sutMessages.map(m=>String(m.id)===String(id)?{...m,read_at:new Date().toISOString()}:m);render()}
function adminMessageText(){return document.getElementById('adminMessage')?.value.trim()||''}
function adminSendWhatsApp(){if(!isAdmin()||sessionStorage.getItem('sut_admin_reauth')!=='1')return;const msg=adminMessageText();if(!msg)return toast('Write a message first');const selected=[...(document.getElementById('adminRecipientList')?.selectedOptions||[])];if(selected.length>1){toast('Select one recipient at a time to open WhatsApp safely.');return}let phone=(document.getElementById('adminRecipientPhone')?.value||'').replace(/\D/g,'');if(!phone){toast('Select a recipient with a WhatsApp phone number, or enter one manually.');return}window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'_blank','noopener,noreferrer')}
function adminSendEmail(){if(!isAdmin()||sessionStorage.getItem('sut_admin_reauth')!=='1')return;const msg=adminMessageText();if(!msg)return toast('Write a message first');const selected=[...(document.getElementById('adminRecipientList')?.selectedOptions||[])];if(selected.length>1){toast('Select one recipient at a time to open an email draft safely.');return}const email=document.getElementById('adminRecipientEmail')?.value.trim()||'';if(!email){toast('Select a recipient with an email address, or enter one manually.');return}const subject=document.getElementById('adminRecipientType')?.value==='all'?'SUT Announcement':'SUT Account Notice';window.location.href=`mailto:${encodeURIComponent(email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(msg)}`}
async function adminCompose(event){event.preventDefault();if(!isAdmin()||sessionStorage.getItem('sut_admin_reauth')!=='1')return;const msg=adminMessageText();if(!msg)return;const sb=window.sutSupabase;const list=document.getElementById('adminRecipientList');const selected=[...(list?.selectedOptions||[])].map(o=>adminRecipientCache.find(r=>o.value===r.kind+'|'+r.id)).filter(Boolean);if(!selected.length){toast('Load recipients and select one or more users/stores first.');return}const status=document.getElementById('adminRecipientStatus');if(status)status.textContent=`Sending in-app message to ${selected.length} selected recipient(s)…`;try{const rows=selected.filter(r=>r.kind==='User').map(r=>({sender_id:state.user.id,recipient_id:r.id,title:'SUT Announcement',body:msg,channel:'in_app',status:'sent',created_at:new Date().toISOString()}));if(!rows.length)throw new Error('In-app messages target user accounts. Select user recipients; store records alone are not message recipients.');const {error}=await sb.from('sut_messages').insert(rows);if(error)throw error;if(status)status.textContent=`Saved ${rows.length} in-app message(s). Delivery means accepted by the database, not confirmed read.`;toast(`Saved ${rows.length} in-app message(s) for selected user(s).`)}catch(e){if(status)status.textContent='In-app send failed: '+e.message;console.error('SUT in-app messaging:',e);toast('In-app send failed. Apply the included Supabase SQL migration, then reload and retry. Error: '+e.message)}}
async function loadAdminQueue(kind){if(!isAdmin()||sessionStorage.getItem('sut_admin_reauth')!=='1'||!window.sutSupabase)return;const host=document.getElementById('adminQueue');if(!host)return;host.innerHTML='<h3>Loading live records…</h3>';const sb=window.sutSupabase;try{let data=[];if(kind==='products'){const r=await sb.from('products').select('id,title,status,price,currency,store_id,created_at').order('created_at',{ascending:false}).limit(100);if(r.error)throw r.error;data=r.data||[];host.innerHTML='<h3>Product moderation</h3><div class="list">'+data.map(x=>`<div class="item"><span class="grow"><b>${esc(x.title)}</b><small class="meta">${esc(x.status)} · ${esc(x.currency)} ${esc(x.price)}</small></span><button class="btn" onclick="adminEditProduct('${esc(x.id)}','${esc(x.title)}','${esc(x.price)}')">Edit</button><button class="btn" onclick="adminProductStatus('${esc(x.id)}','${x.status==='suspended'?'published':'suspended'}')">${x.status==='suspended'?'Restore':'Suspend'}</button><button class="btn" onclick="adminWarnListing('${esc(x.id)}','${esc(x.title)}')">Warn seller</button></div>`).join('')+'</div>'}else if(kind==='stores'){const r=await sb.from('stores').select('id,store_name,status,city,country').order('store_name').limit(100);if(r.error)throw r.error;data=r.data||[];host.innerHTML='<h3>Store management</h3><div class="list">'+data.map(x=>`<div class="item"><span class="grow"><b>${esc(x.store_name)}</b><small class="meta">${esc(x.city||x.country||'')} · ${esc(x.status)}</small></span><button class="btn" onclick="adminStoreStatus('${esc(x.id)}','${x.status==='suspended'?'active':'suspended'}')">${x.status==='suspended'?'Reactivate':'Suspend'}</button></div>`).join('')+'</div>'}else{const r=await sb.from('reports').select('id,target_type,target_id,reason,details,status,created_at').order('created_at',{ascending:false}).limit(100);if(r.error)throw r.error;data=r.data||[];host.innerHTML='<h3>Reports</h3><div class="list">'+data.map(x=>`<div class="item"><span class="grow"><b>${esc(x.reason)}</b><small class="meta">${esc(x.target_type)} · ${esc(x.status)}</small><small>${esc(x.details||'')}</small></span><button class="btn" onclick="adminReportStatus('${esc(x.id)}','reviewing')">Review</button><button class="btn" onclick="adminReportStatus('${esc(x.id)}','resolved')">Resolve</button></div>`).join('')+'</div>'}if(!data.length)host.innerHTML+='<p class="empty">No records found.</p>'}catch(e){host.innerHTML='<h3>Management workspace</h3><p class="notice">Could not load this queue. The current database permissions may not allow this operation.</p>';console.warn('SUT admin queue:',e.message)}}
async function adminEditProduct(id,title,price){if(!isAdmin()||sessionStorage.getItem('sut_admin_reauth')!=='1')return;const nextTitle=prompt('Edit product title',title);if(nextTitle===null)return;const nextPrice=prompt('Edit product price',String(price));if(nextPrice===null)return;const n=Number(nextPrice);if(!nextTitle.trim()||!Number.isFinite(n)||n<0){toast('Enter a valid title and non-negative price');return}const {error}=await window.sutSupabase.from('products').update({title:nextTitle.trim(),price:n,updated_at:new Date().toISOString()}).eq('id',id);if(error){toast('Product edit failed: '+error.message);return}toast('Product updated');await loadAdminQueue('products');await loadSUTCatalog()}
async function adminWarnListing(id,title){if(!isAdmin()||sessionStorage.getItem('sut_admin_reauth')!=='1')return;const sb=window.sutSupabase;if(!sb)return;const reason=prompt(`Write the reason for warning the seller about: ${title}`,'Please review this listing and ensure it follows SUT marketplace rules.');if(reason===null)return;if(!reason.trim())return toast('Enter a warning reason first.');try{const {data:product,error:productError}=await sb.from('products').select('id,title,store_id').eq('id',id).maybeSingle();if(productError)throw productError;if(!product?.store_id)throw new Error('The listing is not linked to a store.');const {data:store,error:storeError}=await sb.from('stores').select('id,store_name,owner_id').eq('id',product.store_id).maybeSingle();if(storeError)throw storeError;if(!store?.owner_id)throw new Error('Could not identify the store owner account.');const body=`SUT SELLER WARNING\n\nStore: ${store.store_name||'Your store'}\nListing: ${product.title||title}\nReference: ${product.id}\n\nReason: ${reason.trim()}\n\nPlease review and correct this listing. If you believe this warning is incorrect, contact SUT support.`;const {error}=await sb.from('sut_messages').insert({sender_id:state.user.id,recipient_id:store.owner_id,title:'SUT Seller Warning',body,channel:'in_app',status:'sent',created_at:new Date().toISOString()});if(error)throw error;toast('Warning notification saved to the seller’s SUT inbox.');}catch(e){console.error('SUT admin warning:',e);toast('Warning was NOT sent: '+e.message+'. Confirm the in-app messaging migration and admin RLS policy are applied.')}}
async function adminProductStatus(id,status){if(!isAdmin()||sessionStorage.getItem('sut_admin_reauth')!=='1')return;const {error}=await window.sutSupabase.from('products').update({status,updated_at:new Date().toISOString()}).eq('id',id);if(error){toast('Action failed: '+error.message);return}toast('Product status updated');await loadAdminQueue('products');await loadSUTCatalog()}
async function adminStoreStatus(id,status){if(!isAdmin()||sessionStorage.getItem('sut_admin_reauth')!=='1')return;const {error}=await window.sutSupabase.from('stores').update({status}).eq('id',id);if(error){toast('Action failed: '+error.message);return}toast('Store status updated');await loadAdminQueue('stores');await loadSUTCatalog()}
async function adminReportStatus(id,status){if(!isAdmin()||sessionStorage.getItem('sut_admin_reauth')!=='1')return;const {error}=await window.sutSupabase.from('reports').update({status}).eq('id',id);if(error){toast('Action failed: '+error.message);return}toast('Report status updated');await loadAdminQueue('reports');await loadAdminStats(false)}
async function respondToRequest(id){if(!requireSignedIn())return;const req=state.requests.find(r=>String(r[5])===String(id));if(!req){toast('Request is unavailable');return}if(!isSeller()||!state.myStore){toast('Create a store to respond to public requests');go('seller');return}const raw=String(req[6]||'');const match=raw.match(/(?:WhatsApp\s*contact:\s*)?(?:https?:\/\/(?:wa\.me\/|api\.whatsapp\.com\/send\?phone=))?([+]?[0-9][0-9\s().-]{7,18})/i);let phone=match?.[1]?.replace(/\D/g,'')||'';if(phone.startsWith('0'))phone='255'+phone.slice(1);if(phone.length===9)phone='255'+phone;if(phone.length<10||phone.length>15){toast('Buyer WhatsApp contact is missing or invalid. Ask the buyer to update the request contact.');return}const body=`Hello, I can help with your SUT request: ${req[0]}\n\nStore: ${state.myStore.store_name}\nVisit our store: ${directStoreLink(state.myStore.id)}\n\nI am contacting you through Star Universal Trade.`;const url=`https://wa.me/${phone}?text=${encodeURIComponent(body)}`;const opened=window.open(url,'_blank','noopener,noreferrer');if(!opened)window.location.href=url;toast('WhatsApp opened for the buyer. Review the message and press Send.')}
function toggleFav(id){state.favs=fav(id)?state.favs.filter(x=>x!==id):[...state.favs,id];localStorage.setItem('sut_favs',JSON.stringify(state.favs));toast(fav(id)?'Added to wishlist':'Removed from wishlist');render()}
function contact(idOrName){const st=state.stores.find(x=>String(x[0])===String(idOrName)||String(x[1])===String(idOrName)||String(x[6])===String(idOrName));const raw=st?.[7]||'';if(!raw){toast('This store has not added a WhatsApp contact number yet.');return}let url=raw;if(/^\+?[0-9\s().-]+$/.test(raw)){try{url=normalizeContact(raw)}catch(e){toast(e.message);return}}if(!/^https:\/\/(wa\.me\/|api\.whatsapp\.com\/)/i.test(url)){toast('This store contact link is not a valid WhatsApp link.');return}window.open(url,'_blank','noopener,noreferrer')}
async function copyDirectLink(value,label='Link copied'){try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(value);toast(label)}else{window.prompt('Copy this text',value)}}catch(e){window.prompt('Copy this text',value)}}
function share(id){const z=prod(id);if(!z)return;state.share={kind:'product',id,title:z.title,url:directProductLink(id),description:`${z.title} · ${money(z.price)} · ${z.seller}`,image:z.img};render()}
function storeAvatarData(store){const name=String(store?.[1]||'SUT Store').trim();const category=String(store?.[2]||'Discover our store').trim();const safe=(v)=>String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g,'&apos;');const lines=[];let rest=name;while(rest.length>22&&lines.length<2){let cut=rest.lastIndexOf(' ',22);if(cut<8)cut=22;lines.push(rest.slice(0,cut));rest=rest.slice(cut).trim()}lines.push(rest);const titleSize=lines.some(x=>x.length>18)?43:lines.some(x=>x.length>13)?50:60;const titleSvg=lines.slice(0,3).map((line,i)=>`<text x="600" y="${390+i*64}" text-anchor="middle" font-family="Arial,sans-serif" font-size="${titleSize}" font-weight="800" fill="#fff8df">${safe(line)}</text>`).join('');const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1200" viewBox="0 0 1200 1200"><defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#061427"/><stop offset=".55" stop-color="#132e4b"/><stop offset="1" stop-color="#020813"/></linearGradient><linearGradient id="gold"><stop stop-color="#f5d36b"/><stop offset="1" stop-color="#c18b20"/></linearGradient></defs><rect width="1200" height="1200" rx="64" fill="url(#bg)"/><rect x="38" y="38" width="1124" height="1124" rx="48" fill="none" stroke="url(#gold)" stroke-width="4"/><circle cx="600" cy="180" r="62" fill="none" stroke="url(#gold)" stroke-width="3"/><text x="600" y="198" text-anchor="middle" font-family="Georgia,serif" font-size="52" font-weight="bold" fill="#f5d36b">S</text><text x="600" y="290" text-anchor="middle" font-family="Arial,sans-serif" font-size="22" letter-spacing="7" fill="#f5d36b">WELCOME TO</text>${titleSvg}<path d="M240 625 H960" stroke="url(#gold)" stroke-width="2"/><text x="600" y="700" text-anchor="middle" font-family="Arial,sans-serif" font-size="29" fill="#d9e5f2">${safe(category.slice(0,40))}</text><text x="600" y="790" text-anchor="middle" font-family="Arial,sans-serif" font-size="34" font-weight="700" fill="#f5d36b">VISIT OUR STORE</text><text x="600" y="845" text-anchor="middle" font-family="Arial,sans-serif" font-size="24" fill="#ffffff">Explore our collection today</text><rect x="410" y="920" width="380" height="64" rx="32" fill="url(#gold)"/><text x="600" y="961" text-anchor="middle" font-family="Arial,sans-serif" font-size="25" font-weight="700" fill="#061427">DISCOVER NOW ↗</text><text x="600" y="1080" text-anchor="middle" font-family="Arial,sans-serif" font-size="22" fill="#d9e5f2">Powered by Star Universal Trade</text></svg>`;return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)}

async function shareImageData(url){try{const r=await fetch(url,{mode:'cors',cache:'force-cache'});if(!r.ok)throw new Error('cover fetch failed');const blob=await r.blob();return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)})}catch(e){return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="470"><defs><linearGradient id="c" x2="1" y2="1"><stop stop-color="#173b58"/><stop offset="1" stop-color="#07182b"/></linearGradient></defs><rect width="1200" height="470" fill="url(#c)"/><text x="600" y="250" text-anchor="middle" fill="#e9bd55" font-size="58" font-family="Arial">STAR UNIVERSAL TRADE</text></svg>')}}
function storeById(id){return state.stores.find(x=>String(x[0])===String(id)||String(x[6])===String(id))||null}
function directStoreShareLink(id){const u=new URL('/api/store-share',location.origin);u.searchParams.set('id',String(id));return u.href}
async function makeStoreQr(url){if(!window.QRCode)throw new Error('QR generator did not load');const host=document.createElement('div');new QRCode(host,{text:url,width:560,height:560,colorDark:'#07182b',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.H});const canvas=host.querySelector('canvas');if(canvas)return canvas.toDataURL('image/png');const img=host.querySelector('img');if(img?.src){const image=new Image();image.src=img.src;await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject});const c=document.createElement('canvas');c.width=560;c.height=560;c.getContext('2d').drawImage(image,0,0,560,560);return c.toDataURL('image/png')}throw new Error('QR generation failed')}
function loadCanvasImage(src){return new Promise(resolve=>{const im=new Image();im.crossOrigin='anonymous';im.onload=()=>resolve(im);im.onerror=()=>resolve(null);im.src=src})}
async function storeQrCardPng(s){const target=directStoreLink(s[0]);const qrData=await makeStoreQr(target);const [cover,qr]=await Promise.all([loadCanvasImage(categoryCover(s[2])),loadCanvasImage(qrData)]);const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=1500;const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Canvas is not supported');const grad=ctx.createLinearGradient(0,0,1200,1500);grad.addColorStop(0,'#07182b');grad.addColorStop(1,'#163e60');ctx.fillStyle=grad;ctx.fillRect(0,0,1200,1500);if(cover){const scale=Math.max(1200/cover.width,520/cover.height);const w=cover.width*scale,h=cover.height*scale;ctx.save();ctx.beginPath();ctx.rect(0,0,1200,520);ctx.clip();ctx.drawImage(cover,(1200-w)/2,(520-h)/2,w,h);ctx.restore()}else{ctx.fillStyle='#183d5d';ctx.fillRect(0,0,1200,520)}const shade=ctx.createLinearGradient(0,250,0,560);shade.addColorStop(0,'rgba(7,24,43,0)');shade.addColorStop(1,'rgba(7,24,43,.96)');ctx.fillStyle=shade;ctx.fillRect(0,0,1200,560);ctx.fillStyle='#e9bd55';ctx.font='bold 34px Arial';ctx.fillText('STAR UNIVERSAL TRADE',70,590);ctx.fillStyle='#ffffff';ctx.font='bold 64px Arial';const name=String(s[1]||'SUT Store');let line=name;if(ctx.measureText(line).width>1000){while(line.length>3&&ctx.measureText(line+'…').width>1000)line=line.slice(0,-1);line+='…'}ctx.fillText(line,70,685);ctx.fillStyle='#c9d5e2';ctx.font='30px Arial';ctx.fillText(String(s[2]||'General')+'  ·  '+String(s[3]||'Connect directly'),70,745);ctx.fillStyle='#ffffff';ctx.fillRect(690,810,440,440);if(qr)ctx.drawImage(qr,710,830,400,400);ctx.fillStyle='#e9bd55';ctx.font='bold 30px Arial';ctx.fillText('SCAN TO VISIT THIS STORE',70,900);ctx.fillStyle='#ffffff';ctx.font='26px Arial';const desc=String(s[8]||'Discover this store on Star Universal Trade.');const words=desc.split(/\s+/);let row='',y=970;for(const word of words){const next=row?row+' '+word:word;if(ctx.measureText(next).width>560){ctx.fillText(row,70,y);row=word;y+=42;if(y>1160)break}else row=next}if(row&&y<=1160)ctx.fillText(row,70,y);ctx.fillStyle='#e9bd55';ctx.font='bold 24px Arial';ctx.fillText('Powered by Rex International Technologies',70,1390);ctx.fillStyle='#ffffff';ctx.font='20px Arial';ctx.fillText(location.origin+'/#/store/'+encodeURIComponent(s[0]),70,1440);return canvas.toDataURL('image/png')}
async function shareStore(id){const s=storeById(id);if(!s){toast('Store could not be found');return}const url=directStoreShareLink(s[0]);state.share={kind:'store-link',id:s[0],title:s[1],description:s[8]||`${s[2]||'Store'} on Star Universal Trade`,url,image:categoryCover(s[2])};render()}
async function getStoreQrCode(id){const s=storeById(id);if(!s){toast('Store could not be found');return}try{toast('Generating your store QR poster…');const image=await storeQrCardPng(s);state.share={kind:'store-qr',id:s[0],title:s[1],description:s[8]||'Scan to visit this store on SUT.',url:directStoreLink(s[0]),image};render()}catch(e){console.error('SUT store QR poster:',e);toast('Could not generate the QR poster: '+(e.message||'Please reload and try again.'))}}
async function nativeShare(){if(!state.share)return;const x=state.share;const text=`${x.title}\n${x.description||''}\n\n${x.url}\n\n${x.kind==='product'?'View product details.':'Visit this store on Star Universal Trade.'}\nPowered by Star Universal Trade`;try{if(navigator.share){if(x.kind==='store-link'){await navigator.share({title:x.title,text:`${x.title}\n${x.description||'Discover this store on SUT.'}`,url:x.url});toast('Store link shared. The public page supplies the rich WhatsApp preview when deployed.');return}let files=[];if(x.image){try{const f=await imageFile(x.image,`${makeSlug(x.title)}-SUT.png`);if(f&&navigator.canShare?.({files:[f]}))files=[f]}catch(e){}}const payload={title:x.title,text,url:x.url};if(files.length)payload.files=files;await navigator.share(payload);toast(files.length?'Image shared':'Share sheet opened; use Download PNG if this app does not accept image files')}else{copyDirectLink(text,`${x.kind==='product'?'Product':'Store'} link copied`)}}catch(e){if(e?.name!=='AbortError')toast('Sharing was cancelled')}}
async function downloadShareImage(){if(!state.share?.image)return;const x=state.share;try{const img=new Image();img.decoding='sync';img.src=x.image;await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('Could not render the promotion image'))});const canvas=document.createElement('canvas');canvas.width=img.naturalWidth||1200;canvas.height=img.naturalHeight||1200;const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Image canvas is not available');ctx.fillStyle='#061427';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('PNG export failed');const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${makeSlug(x.title||'sut-store')}-${x.kind==='store-qr'?'SUT-Store-QR':'SUT-promo'}.png`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast(x.kind==='store-qr'?'Store QR Code PNG downloaded.':'PNG image downloaded.')}catch(e){console.error('SUT promo image download:',e);try{const blob=new Blob([decodeURIComponent(x.image.split(',')[1]||'')],{type:'image/svg+xml;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${makeSlug(x.title||'sut-store')}-SUT-promo.svg`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Downloaded SVG fallback. If your gallery cannot preview SVG, open it in a browser or use Share Image.')}catch(err){toast('Could not export the image on this browser. Use Share Image or open the preview and try again.')}}}
function closeShare(){state.share=null;render()}
function shareLayer(){if(!state.share)return '';const x=state.share;const product=x.kind==='product',qr=x.kind==='store-qr',label=product?'Product':'Store';if(x.kind==='store-link')return `<div class="share-overlay" onclick="closeShare()"><section class="share-dialog share-card" onclick="event.stopPropagation()"><button class="icon share-close" onclick="closeShare()" aria-label="Close">×</button><div class="share-preview store-share-preview"><img src="${esc(x.image||'assets/sut-icon.png')}" alt="${esc(x.title)}"><div class="share-preview-copy"><div class="ey">SUT STORE LINK PREVIEW</div><h2>${esc(x.title)}</h2><p>${esc(x.description||'Discover this store on Star Universal Trade.')}</p><small>Powered by Star Universal Trade</small></div></div><label class="meta" for="storeShareUrl">Public store sharing link</label><input id="storeShareUrl" class="input" value="${esc(x.url)}" readonly onclick="this.select()"><div class="share-actions"><button class="btn" onclick="copyDirectLink('${esc(x.url)}','Store link copied')">Copy Link</button><button class="btn primary" onclick="nativeShare()">Share Store</button><a class="btn blue" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent(x.title+' — '+(x.description||'Discover this store on SUT')+'\n'+x.url)}">WhatsApp</a></div><div class="notice">WhatsApp-style rich preview is generated from the public store page after deployment to Vercel. Localhost cannot provide a public crawler preview.</div></section></div>`;return `<div class="share-overlay" onclick="closeShare()"><section class="share-dialog share-card" onclick="event.stopPropagation()"><button class="icon share-close" onclick="closeShare()" aria-label="Close">×</button><div class="share-preview ${qr?'store-qr-preview':(product?'':'store-share-preview')}"><img src="${esc(x.image||'assets/sut-icon.png')}" alt="${esc(x.title)}" onerror="this.src='assets/sut-icon.png'"><div class="share-preview-copy"><div class="ey">${qr?'STORE QR CODE':'AVAILABLE ON SUT'}</div><h2>${esc(x.title)}</h2><p>${esc(x.description||'Discover on Star Universal Trade.')}</p><small>Powered by Star Universal Trade</small></div></div>${qr?`<div class="notice">Scan this QR Code to open this exact store. The QR points to the public store route on this SUT domain.</div>`:`<input class="input" aria-label="Direct link" value="${esc(x.url)}" readonly onclick="this.select()">`}<div class="share-actions">${qr?`<button class="btn primary" onclick="downloadShareImage()">Download Store QR Code (PNG)</button><button class="btn blue" onclick="nativeShare()">Share QR Image</button>`:`<a class="btn primary" href="${esc(x.url)}" target="_blank" rel="noopener">View Product</a><button class="btn" onclick="copyDirectLink('${esc(x.url)}','Product link copied')">Copy Link</button><button class="btn blue" onclick="nativeShare()">Share Product</button>`}</div></section></div>`}
function render(){document.body.classList.toggle('light',state.theme==='light');document.documentElement.lang=state.lang==='sw'?'sw':state.lang;const b=state.route.split('/')[0],arg=decodeURIComponent(state.route.split('/')[1]||'');let c=b==='home'?home():b==='products'?products():b==='advanced-search'?advancedSearch():b==='product'?product(arg):b==='stores'?stores():b==='store'?store(arg):b==='requests'?requests():b==='request'?request(arg):b==='report'?reportPage(state.route.split('/').slice(1).join('/')):b==='login'?auth():b==='register'?auth(true):b==='account'?account():b==='seller'?seller():b==='seller-dashboard'?dashboard():b==='upload'?upload():b==='wishlist'?wishlist():b==='notifications'?notifications():b==='settings'?settings():b==='about'?about():b==='media'?media():b==='contact'?contactPage():b==='help'?help():b==='privacy'?privacy():b==='terms'?terms():b==='admin'?admin():home();document.getElementById('app').innerHTML=head()+c+foot()+mobileNav()+sideMenu()+shareLayer()}

// Supabase integration: public client key only. Database RLS remains the security boundary.
async function submitAuth(event,registerMode){
  event.preventDefault();
  if(!window.sutSupabase){toast('Supabase configuration is missing');return}
  const email=document.getElementById('email')?.value?.trim();
  const password=document.getElementById('password')?.value;
  const fullName=document.getElementById('name')?.value?.trim()||'';
  const button=event.currentTarget.querySelector('button[type="submit"],button:not([type])');
  if(button){button.disabled=true;button.textContent=registerMode?'Creating account…':'Signing in…'}
  try{
    let result;
    if(registerMode){result=await window.sutSupabase.auth.signUp({email,password,options:{data:{full_name:fullName}}});}
    else{result=await window.sutSupabase.auth.signInWithPassword({email,password});}
    if(result.error)throw result.error;
    if(registerMode && !result.data.session){toast('Account created. Check your email to confirm it, then sign in.');go('login');return}
    await loadSUTUser(result.data.user||result.data.session?.user);
    await loadSUTCatalog();
    toast(registerMode?'SUT account created successfully':'Signed in successfully');go('account');render();
  }catch(err){toast(err?.message||'Authentication failed');}
  finally{if(button){button.disabled=false;button.textContent=registerMode?'Create Account':'Sign in'}}
}
async function signInWithGoogle(){
  if(!window.sutSupabase){toast('Supabase configuration is missing');return}
  try{
    // Keep the app route out of the OAuth redirect URL fragment. OAuth tokens/code
    // and hash-based SPA routing must not compete for the same URL fragment.
    sessionStorage.setItem('sut_oauth_return_to_account','1');
    const {error}=await window.sutSupabase.auth.signInWithOAuth({
      provider:'google',
      options:{redirectTo:location.origin+location.pathname}
    });
    if(error){sessionStorage.removeItem('sut_oauth_return_to_account');toast(error.message)}
  }catch(err){sessionStorage.removeItem('sut_oauth_return_to_account');toast(err?.message||'Google sign-in failed')}
}
async function loadSUTUser(authUser){
  if(!authUser){state.user=null;return}
  const sb=window.sutSupabase;
  let name=authUser.user_metadata?.full_name||authUser.user_metadata?.name||authUser.email||'SUT User';
  let roles=['buyer'];
  try{const {data}=await sb.from('profiles').select('full_name').eq('id',authUser.id).maybeSingle();if(data?.full_name)name=data.full_name}catch(e){console.warn('SUT profile read:',e.message)}
  try{const {data,error}=await sb.from('user_roles').select('role').eq('user_id',authUser.id);if(!error&&Array.isArray(data)&&data.length)roles=[...new Set(data.map(x=>x.role))]}catch(e){console.warn('SUT role read:',e.message)}
  state.user={id:authUser.id,email:authUser.email||'',name,roles,role:roles.includes('superadmin')?'superadmin':roles.includes('admin')?'admin':roles.includes('seller')?'seller':roles.includes('moderator')?'moderator':roles.includes('support')?'support':'buyer'};
  state.myStore=null;
  try{const {data,error}=await sb.from('stores').select('id,owner_id,store_name,slug,description,country,city,contact_url,status,category_name').eq('owner_id',authUser.id).limit(1).maybeSingle();if(!error&&data)state.myStore=data;}catch(e){console.warn('SUT owned store read:',e.message)}
}
async function loadSUTCatalog(){
  const sb=window.sutSupabase;if(!sb)return;
  try{
    const [{data:rows,error:pe},{data:storeRows,error:se},{data:cats,error:ce}]=await Promise.all([
      sb.from('products').select('id,store_id,category_id,title,description,price,currency,country,city,availability,content_type,status').eq('status','published').limit(300),
      sb.from('stores').select('id,owner_id,store_name,slug,description,country,city,contact_url,status,category_name').eq('status','active').limit(200),
      sb.from('categories').select('id,name,slug').eq('is_active',true).limit(200)
    ]);
    if(pe)console.warn('SUT products query:',pe.message);
    if(se)console.warn('SUT stores query:',se.message);
    if(ce)console.warn('SUT categories query:',ce.message);
    const validStores=Array.isArray(storeRows)?storeRows:[];
    if(!se){
      let counts={};
      (Array.isArray(rows)?rows:[]).forEach(p=>counts[p.store_id]=(counts[p.store_id]||0)+1);
      state.stores=validStores.map(st=>[st.id,st.store_name||'SUT Store',st.category_name||'General',st.city||st.country||'Location',counts[st.id]||0,(st.store_name||'S').trim().charAt(0).toUpperCase(),st.slug||st.id,st.contact_url||'',st.description||'']);
    }
    const published=Array.isArray(rows)?rows:[];
    if(!pe){
      let mediaByProduct={};
      const ids=published.map(p=>p.id);
      try{const {data:media,error:me}=await sb.from('product_media').select('product_id,media_url,media_type,sort_order').in('product_id',ids).order('sort_order',{ascending:true});if(!me&&Array.isArray(media))for(const m of media){if(m.media_url&&!mediaByProduct[m.product_id])mediaByProduct[m.product_id]=m.media_url}}catch(e){console.warn('SUT media read:',e.message)}
      const storeMap=new Map(validStores.map(x=>[x.id,x]));const catMap=new Map((Array.isArray(cats)?cats:[]).map(x=>[x.id,x.name]));
      state.products=published.map(p=>{const st=storeMap.get(p.store_id)||{};const cat=catMap.get(p.category_id)||'General';const img=mediaByProduct[p.id]||'';return[p.id,p.title||'Untitled product',cat,Number(p.price)||0,st.store_name||'SUT Seller',p.city||st.city||p.country||st.country||'Location','headphones',img,p.store_id,p.status,p.currency,p.availability]});
    }
    render();
  }catch(err){console.warn('SUT catalog load failed:',err.message)}
}
function requireSignedIn(){if(!state.user){toast('Please sign in first');go('login');return false}if(!window.sutSupabase){toast('Supabase is not configured');return false}return true}
function makeSlug(value){return String(value||'store').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,70)||'store'}
async function createSellerStore(event){event.preventDefault();if(!requireSignedIn())return;const sb=window.sutSupabase;const name=document.getElementById('storeName').value.trim();if(!name)return;const button=event.currentTarget.querySelector('button[type="submit"]');if(button){button.disabled=true;button.textContent='Creating store…'}try{const {data:existing,error:existingError}=await sb.from('stores').select('id,store_name').ilike('store_name',name).limit(1);if(existingError)throw existingError;if(existing?.length)throw new Error('This store name is already in use. Choose a different name.');const slug=`${makeSlug(name)}-${state.user.id.slice(0,6)}`;const category=document.getElementById('storeCategory').value;const contact=normalizeContact((document.getElementById('storeCountryCode')?.value||'255')+' '+document.getElementById('storeContact').value.trim());if(!category||!contact)throw new Error('Choose a store category and enter a WhatsApp contact.');const row={owner_id:state.user.id,store_name:name,slug,category_name:category,description:document.getElementById('storeDescription').value.trim()||null,country:document.getElementById('storeCountry').value.trim()||null,city:document.getElementById('storeCity').value.trim()||null,contact_url:contact};const {data,error}=await sb.from('stores').insert(row).select('id,owner_id,store_name,slug,description,country,city,contact_url,status,category_name').single();if(error)throw error;state.myStore=data;await loadSUTCatalog();toast('Store created successfully');go('seller-dashboard');render()}catch(err){console.error('SUT create store:',err);toast(`Could not create store: ${err.message||'database error'}`)}finally{if(button){button.disabled=false;button.textContent='Create Seller Profile'}}}
function applyCountryCode(){const input=document.getElementById('storeContact');if(!input)return;const digits=input.value.replace(/\D/g,'');if(digits.startsWith('0'))input.value=digits.slice(1)}
function normalizeContact(v){if(!v)return null;const raw=String(v).trim();if(/^https:\/\/(wa\.me\/|api\.whatsapp\.com\/)/i.test(raw))return raw;if(!/^[+0-9\s().-]+$/.test(raw))throw new Error('Enter a valid WhatsApp phone number.');let n=raw.replace(/\D/g,'');if(n.startsWith('00'))n=n.slice(2);if(n.startsWith('0'))n='255'+n.slice(1);else if(n.length===9)n='255'+n;if(n.length<10||n.length>15)throw new Error('Check the phone number, including its country code if outside Tanzania.');return `https://wa.me/${n}`}
async function cloudinaryUpload(file){const cfg=window.SUT_CONFIG?.cloudinary;if(!cfg?.cloudName||!cfg?.unsignedPreset)throw new Error('Cloudinary is not configured. Check supabase-config.js SUT_CONFIG.');if(file.size>8*1024*1024)throw new Error(`${file.name} exceeds the 8 MB image limit.`);if(!['image/jpeg','image/png','image/webp','image/avif'].includes(file.type))throw new Error(`${file.name} is not a supported image.`);const fd=new FormData();fd.append('file',file);fd.append('upload_preset',cfg.unsignedPreset);fd.append('folder',cfg.folder||'sut/products');const res=await fetch(`https://api.cloudinary.com/v1_1/${encodeURIComponent(cfg.cloudName)}/image/upload`,{method:'POST',body:fd});const json=await res.json().catch(()=>({}));if(!res.ok||!json.secure_url)throw new Error(json.error?.message||`Cloudinary upload failed (${res.status}).`);return json.secure_url}
async function createProduct(event){event.preventDefault();if(!requireSignedIn())return;if(!state.myStore){toast('Create your store first');go('seller');return}const files=[...(document.getElementById('files')?.files||[])];if(!files.length){toast('Choose at least one product image');return}if(files.length>5){toast('Choose no more than 5 images');return}const sb=window.sutSupabase;const form=event.currentTarget;const button=form.querySelector('button[type="submit"]');if(button){button.disabled=true;button.textContent='Saving product…'}let productId=null;try{const categoryName=document.getElementById('productCategory').value;let categoryId=null;if(categoryName){const {data:cat,error:catErr}=await sb.from('categories').select('id').eq('name',categoryName).eq('is_active',true).maybeSingle();if(catErr)throw catErr;if(cat)categoryId=cat.id}const row={store_id:state.myStore.id,category_id:categoryId,title:document.getElementById('productTitle').value.trim(),description:document.getElementById('productDescription').value.trim(),price:Number(document.getElementById('productPrice').value),currency:document.getElementById('productCurrency').value,country:document.getElementById('productCountry').value.trim()||null,city:document.getElementById('productCity').value.trim()||null,availability:document.getElementById('productAvailability').value,content_type:'image',status:'draft'};const {data:product,error}=await sb.from('products').insert(row).select('id').single();if(error)throw error;productId=product.id;const urls=[];for(const file of files)urls.push(await cloudinaryUpload(file));const mediaRows=urls.map((url,i)=>({product_id:productId,media_url:url,media_type:'image',alt_text:row.title,sort_order:i}));const {error:mediaErr}=await sb.from('product_media').insert(mediaRows);if(mediaErr)throw mediaErr;const {error:publishErr}=await sb.from('products').update({status:'published',updated_at:new Date().toISOString()}).eq('id',productId).eq('store_id',state.myStore.id);if(publishErr)throw publishErr;toast('Product published successfully');await loadSUTCatalog();go('seller-dashboard');render()}catch(err){console.error('SUT product create:',err);toast(productId?`Product saved as draft. Finish failed: ${err.message||'unknown error'}`:`Could not save product: ${err.message||'unknown error'}`)}finally{if(button){button.disabled=false;button.textContent='Save and Publish Product'}}}
function reportPage(arg=''){if(!requireSignedIn())return `<main class="wrap"><div class="empty"><h2>Sign in to report</h2><button class="btn primary" onclick="go('login')">Sign in</button></div></main>`;const [targetType,targetId]=arg.split('/');return `<main class="wrap"><div class="title"><div><div class="ey">Trust & Safety</div><h1>Report a ${esc(targetType==='product'?'product listing':targetType==='store'?'store':'user')}</h1><p>Tell SUT what happened. Keep the report factual and brief.</p></div></div><form class="panel" onsubmit="submitReport(event,'${esc(targetType||'user')}','${esc(targetId||'')}')"><div class="formgrid"><div class="field"><label>What is the issue?</label><select id="reportReason" required><option value="">Choose a reason</option><option>Fraud or scam</option><option>False or misleading information</option><option>Counterfeit or prohibited item</option><option>Harassment or abuse</option><option>Suspicious contact or payment request</option><option>Other policy concern</option></select></div><div class="field full"><label>Short explanation</label><textarea id="reportDetails" required minlength="8" maxlength="1000" placeholder="Briefly explain why you are reporting this account or listing."></textarea></div></div><div class="notice">Reports are reviewed under SUT moderation rules. Do not include passwords or sensitive personal information.</div><button class="btn primary" type="submit">Submit Report</button><button class="btn" type="button" onclick="history.back()">Cancel</button></form></main>`}
async function submitReport(event,targetType,targetId){event.preventDefault();if(!requireSignedIn())return;const sb=window.sutSupabase;const reason=document.getElementById('reportReason').value;const details=document.getElementById('reportDetails').value.trim();try{const row={reporter_id:state.user.id,target_type:targetType||'user',target_id:targetId||null,reason,details,status:'open'};const {error}=await sb.from('reports').insert(row);if(error)throw error;toast('Report submitted for review');go('account')}catch(e){console.error('SUT report submission:',e);toast('Report could not be saved. The reports table/policies may need matching reporter_id and target fields: '+(e.message||'database error'))}}
async function submitPublicRequest(event){event.preventDefault();if(!requireSignedIn())return;const sb=window.sutSupabase;const title=document.getElementById('requestTitle').value.trim();const categoryName=document.getElementById('requestCategory').value;const budgetValue=document.getElementById('requestBudget').value;try{const buyerWhatsApp=normalizeContact(document.getElementById('requestWhatsapp').value.trim());if(!buyerWhatsApp)throw new Error('Enter your WhatsApp contact so sellers can reach you directly.');let categoryId=null;if(categoryName){const {data,error}=await sb.from('categories').select('id').eq('name',categoryName).eq('is_active',true).maybeSingle();if(error)throw error;if(data)categoryId=data.id}const row={buyer_id:state.user.id,title,description:[document.getElementById('requestDescription').value.trim(),`WhatsApp contact: ${buyerWhatsApp}`].filter(Boolean).join('\n\n')||null,category_id:categoryId,budget:budgetValue?Number(budgetValue):null,currency:document.getElementById('requestCurrency').value,country:document.getElementById('requestCountry').value.trim()||null,city:document.getElementById('requestCity').value.trim()||null,status:'open'};const {error}=await sb.from('public_requests').insert(row);if(error)throw error;state.buyForMe=null;toast('Your request has been published');await loadSUTRequests();go('requests');render()}catch(err){console.error('SUT request create:',err);toast(`Could not publish request: ${err.message||'database error'}`)}}
async function loadSUTRequests(){const sb=window.sutSupabase;if(!sb)return;try{let q=sb.from('public_requests').select('id,buyer_id,title,description,budget,currency,country,city,status,created_at,category_id').eq('status','open').order('created_at',{ascending:false}).limit(100);if(!state.user){state.requests=[];return}if(!isSeller())q=q.eq('buyer_id',state.user.id);const {data,error}=await q;if(error)throw error;const cats=await sb.from('categories').select('id,name');const cm=new Map((cats.data||[]).map(c=>[c.id,c.name]));state.requests=(data||[]).map(r=>[r.title,cm.get(r.category_id)||'General',[r.city,r.country].filter(Boolean).join(', ')||'Location',r.budget==null?'Contact for budget':`${new Intl.NumberFormat('en-TZ').format(r.budget)} ${r.currency}`,new Date(r.created_at).toLocaleString(),r.id,r.description||'',r.buyer_id])}catch(e){console.warn('SUT requests load:',e.message)}}
async function closePublicRequest(id){if(!requireSignedIn())return;const req=state.requests.find(r=>String(r[5])===String(id));if(!req||req[7]!==state.user.id){toast('Only the request owner can close this request');return}if(!confirm('Close this request? Sellers will no longer be able to respond while it is closed.'))return;const {error}=await window.sutSupabase.from('public_requests').update({status:'closed'}).eq('id',id).eq('buyer_id',state.user.id);if(error){toast('Could not close request: '+error.message);return}toast('Request closed');await loadSUTRequests();render()}

async function loadMyProducts(showToast=false){await loadSUTCatalog();if(showToast)toast('Product list refreshed')}
async function loadAdminStats(showToast=false){if(!isAdmin()||!window.sutSupabase)return;const sb=window.sutSupabase;const counts=[['users','profiles'],['stores','stores'],['products','products'],['requests','public_requests'],['reports','reports'],['categories','categories']];const result={};await Promise.all(counts.map(async([key,table])=>{try{const {count,error}=await sb.from(table).select('*',{count:'exact',head:true});if(error)throw error;result[key]=count??0}catch(e){result[key]='N/A';console.warn('SUT admin count',table,e.message)}}));state.backendStats=result;if(showToast)toast('Admin counts refreshed');if(state.route.split('/')[0]==='admin')render()}
async function bootSUTBackend(){
  if(!window.sutSupabase){console.error('SUT Supabase client not initialized.');return}
  try{
    const {data:{session},error}=await window.sutSupabase.auth.getSession();if(error)throw error;
    await loadSUTUser(session?.user||null);
    await loadSUTCatalog();
    await loadSUTRequests();
    if(isAdmin())await loadAdminStats(false);
    window.sutSupabase.auth.onAuthStateChange((event,session)=>{setTimeout(async()=>{await loadSUTUser(session?.user||null);if(event==='SIGNED_IN'||event==='TOKEN_REFRESHED'){await loadSUTCatalog();await loadSUTRequests();if(isAdmin())await loadAdminStats(false)}if(event==='SIGNED_OUT'){state.myStore=null;state.backendStats=null}render()},0)});
    if(session?.user && sessionStorage.getItem('sut_oauth_return_to_account')==='1'){
      sessionStorage.removeItem('sut_oauth_return_to_account');
      if(state.route!=='account'){state.route='account';location.hash='#/account'}
    }
    render();
  }catch(err){console.error('SUT backend initialization:',err.message);toast('Backend connection issue. See README troubleshooting.')}
}

window.addEventListener('DOMContentLoaded',()=>{setTimeout(()=>document.getElementById('splash')?.classList.add('hide'),850);render();if(window.matchMedia('(display-mode: standalone)').matches)document.querySelectorAll('[data-install-app]').forEach(x=>x.style.display='none');bootSUTBackend()});
